const fragmentosCodigo = {
    crecimientoExponencial: `def expresion_crecimiento_exponencial(cantidad_inicial: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:
    return decimal(cantidad_inicial) * sp.exp(decimal(constante_k) * variable)`,
    decaimientoExponencial: `def expresion_decaimiento_exponencial(cantidad_inicial: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:
    return decimal(cantidad_inicial) * sp.exp(-decimal(constante_k) * variable)`,
    entradaConstante: `def expresion_crecimiento_entrada_constante(cantidad_inicial: float, constante_k: float, entrada_constante: float, variable: sp.Symbol) -> sp.Expr:
    k = decimal(constante_k)
    b = decimal(entrada_constante)
    return (decimal(cantidad_inicial) + b / k) * sp.exp(k * variable) - b / k`,
    caidaResistencia: `def expresion_caida_resistencia(velocidad_inicial: float, gravedad: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:
    k = decimal(constante_k)
    velocidad_limite = decimal(gravedad) / k
    return velocidad_limite + (decimal(velocidad_inicial) - velocidad_limite) * sp.exp(-k * variable)`,
    newton: `def expresion_newton(temperatura_inicial: float, temperatura_ambiente: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:
    return decimal(temperatura_ambiente) + (decimal(temperatura_inicial) - decimal(temperatura_ambiente)) * sp.exp(-decimal(constante_k) * variable)`,
    mezclaConstante: `def expresion_mezcla_volumen_constante(sal_inicial: float, equilibrio: float, alfa: float, variable: sp.Symbol) -> sp.Expr:
    return decimal(equilibrio) + (decimal(sal_inicial) - decimal(equilibrio)) * sp.exp(-decimal(alfa) * variable)`,
    mezclaVariable: `def expresion_mezcla_volumen_variable(
    sal_inicial: float,
    volumen_inicial: float,
    concentracion_entrada: float,
    delta_volumen: float,
    exponente: float,
    variable: sp.Symbol,
) -> sp.Expr:
    volumen = decimal(volumen_inicial) + decimal(delta_volumen) * variable
    return decimal(concentracion_entrada) * volumen + (
        decimal(sal_inicial) - decimal(concentracion_entrada) * decimal(volumen_inicial)
    ) * (decimal(volumen_inicial) / volumen) ** decimal(exponente)`
};

const codigoProyecto = {
    "simbolicoCompleto": "\"\"\"Motor simbólico del proyecto usando SymPy.\n\nEl sistema mantiene los cálculos numéricos controlados, pero construye las\nfunciones principales con SymPy para generar fórmulas LaTeX consistentes y\nvalidar simbólicamente las expresiones de cada modelo.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Final\n\nimport sympy as sp\n\nPRECISION_SIMBOLICA: Final[int] = 15\n\n\ndef crear_variable(nombre: str = \"t\") -> sp.Symbol:\n    \"\"\"Crea una variable simbólica real.\"\"\"\n    return sp.symbols(nombre, real=True)\n\n\ndef decimal(valor: float | int) -> sp.Float:\n    \"\"\"Convierte un número Python en número SymPy con precisión controlada.\"\"\"\n    return sp.Float(float(valor), PRECISION_SIMBOLICA)\n\n\ndef latex(expresion: sp.Expr) -> str:\n    \"\"\"Convierte una expresión SymPy a LaTeX.\"\"\"\n    return sp.latex(expresion)\n\n\ndef evaluar(expresion: sp.Expr, variable: sp.Symbol, valor: float | int) -> float:\n    \"\"\"Evalúa una expresión simbólica en un punto y retorna float.\"\"\"\n    return float(sp.N(expresion.subs(variable, decimal(valor))))\n\n\ndef expresion_crecimiento_exponencial(cantidad_inicial: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:\n    return decimal(cantidad_inicial) * sp.exp(decimal(constante_k) * variable)\n\n\ndef expresion_decaimiento_exponencial(cantidad_inicial: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:\n    return decimal(cantidad_inicial) * sp.exp(-decimal(constante_k) * variable)\n\n\ndef expresion_crecimiento_entrada_constante(cantidad_inicial: float, constante_k: float, entrada_constante: float, variable: sp.Symbol) -> sp.Expr:\n    k = decimal(constante_k)\n    b = decimal(entrada_constante)\n    return (decimal(cantidad_inicial) + b / k) * sp.exp(k * variable) - b / k\n\n\ndef expresion_caida_resistencia(velocidad_inicial: float, gravedad: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:\n    k = decimal(constante_k)\n    velocidad_limite = decimal(gravedad) / k\n    return velocidad_limite + (decimal(velocidad_inicial) - velocidad_limite) * sp.exp(-k * variable)\n\n\ndef expresion_newton(temperatura_inicial: float, temperatura_ambiente: float, constante_k: float, variable: sp.Symbol) -> sp.Expr:\n    return decimal(temperatura_ambiente) + (decimal(temperatura_inicial) - decimal(temperatura_ambiente)) * sp.exp(-decimal(constante_k) * variable)\n\n\ndef expresion_mezcla_volumen_constante(sal_inicial: float, equilibrio: float, alfa: float, variable: sp.Symbol) -> sp.Expr:\n    return decimal(equilibrio) + (decimal(sal_inicial) - decimal(equilibrio)) * sp.exp(-decimal(alfa) * variable)\n\n\ndef expresion_mezcla_volumen_variable(\n    sal_inicial: float,\n    volumen_inicial: float,\n    concentracion_entrada: float,\n    delta_volumen: float,\n    exponente: float,\n    variable: sp.Symbol,\n) -> sp.Expr:\n    volumen = decimal(volumen_inicial) + decimal(delta_volumen) * variable\n    return decimal(concentracion_entrada) * volumen + (\n        decimal(sal_inicial) - decimal(concentracion_entrada) * decimal(volumen_inicial)\n    ) * (decimal(volumen_inicial) / volumen) ** decimal(exponente)\n\n\ndef igualdad_funcion(nombre: str, variable: sp.Symbol, expresion: sp.Expr) -> str:\n    \"\"\"Devuelve una igualdad tipo f(t)=... en LaTeX.\"\"\"\n    return rf\"{nombre}({sp.latex(variable)})={sp.latex(expresion)}\"\n\n\ndef paso_sympy(nombre: str, variable: sp.Symbol, expresion: sp.Expr) -> str:\n    \"\"\"Bloque LaTeX compacto para mostrar la función que SymPy evaluará.\"\"\"\n    return rf\"\\boxed{{{igualdad_funcion(nombre, variable, expresion)}}}\"",
    "formulasSimbolicasCompleto": "\"\"\"Fórmulas simbólicas para casos con datos incompletos.\n\nCuando el estudiante no recibe todos los datos numéricos, el sistema no debe\ninventar constantes ni detenerse de forma brusca. Este módulo usa SymPy para\nconstruir el planteamiento algebraico que resolvería el ítem, conservando\nvariables indeterminadas como k, C, R, t, P0, Ta o RC.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any\n\nimport sympy as sp\n\nfrom backend.utils.formato import crear_paso, crear_respuesta_modelo, formatear_numero\nfrom backend.utils.validacion import normalizar_texto\n\nMODULO_FORMULA = \"formula_simbolica\"\n\n\ndef _tiene_valor(datos: dict[str, Any], *campos: str) -> bool:\n    return any(datos.get(campo) not in (None, \"\") for campo in campos)\n\n\ndef _numero_o_simbolo(datos: dict[str, Any], campos: tuple[str, ...], simbolo: str) -> sp.Expr:\n    for campo in campos:\n        valor = datos.get(campo)\n        if valor not in (None, \"\"):\n            try:\n                return sp.Float(float(str(valor).replace(\",\", \".\")), 12)\n            except (TypeError, ValueError):\n                return sp.Symbol(simbolo, real=True)\n    return sp.Symbol(simbolo, real=True)\n\n\ndef _simbolo_tiempo(datos: dict[str, Any], campos: tuple[str, ...] = (\"tiempo_objetivo\", \"tiempo\", \"distancia_objetivo\"), simbolo: str = \"t\") -> sp.Expr:\n    return _numero_o_simbolo(datos, campos, simbolo)\n\n\ndef _latex_igualdad(nombre: str, variable: sp.Symbol | sp.Expr, expresion: sp.Expr) -> str:\n    return rf\"{nombre}({sp.latex(variable)})={sp.latex(expresion)}\"\n\n\ndef _respuesta_formula(\n    *,\n    modulo: str,\n    variante: str,\n    modelo: str,\n    resultado: str,\n    pasos: list[dict[str, str]],\n    resultado_latex: str | None = None,\n) -> dict[str, Any]:\n    return crear_respuesta_modelo(\n        modulo=modulo,\n        variante=variante,\n        modelo=modelo,\n        tipo=MODULO_FORMULA,\n        resultado=resultado,\n        resultado_latex=resultado_latex,\n        unidad=\"fórmula simbólica\",\n        constantes={},\n        pasos=pasos,\n        advertencias=[\n            \"Modo simbólico: se conservan variables indeterminadas porque no se entregaron todos los datos numéricos.\",\n            \"El sistema muestra la fórmula correcta antes de sustituir valores. Matemáticas con casco, no con chanclas.\",\n        ],\n        metadatos={\"uso\": \"planteamiento_con_datos_incompletos\"},\n    )\n\n\ndef formula_crecimiento(datos: dict[str, Any]) -> dict[str, Any]:\n    variante = normalizar_texto(datos.get(\"variante\", \"crecimiento_proporcional\"))\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"formula_simbolica\"))\n    t = sp.Symbol(\"t\", real=True)\n    tx = _simbolo_tiempo(datos, simbolo=\"t_x\")\n    k = _numero_o_simbolo(datos, (\"constante_k\", \"k\"), \"k\")\n\n    if variante in (\"entrada_constante\", \"crecimiento_entrada_constante\", \"lineal_entrada\"):\n        p0 = _numero_o_simbolo(datos, (\"cantidad_inicial\", \"poblacion_inicial\"), \"P_0\")\n        b = _numero_o_simbolo(datos, (\"entrada_constante\", \"b\"), \"b\")\n        expresion = (p0 + b / k) * sp.exp(k * t) - b / k\n        expresion_objetivo = expresion.subs(t, tx)\n        pasos = [\n            crear_paso(\"Identificación del modelo\", \"Existe crecimiento proporcional más una entrada externa constante.\", r\"\\frac{dP}{dt}=kP+b\"),\n            crear_paso(\"Solución simbólica general\", \"Se resuelve como EDO lineal de primer orden; si k o b no aparecen en el enunciado, quedan como parámetros.\", r\"\\begin{gathered}\\frac{dP}{dt}-kP=b\\\\[4px]P(t)=Ce^{kt}-\\frac{b}{k}\\end{gathered}\"),\n            crear_paso(\"Aplicación de condición inicial\", \"Con P(0)=P_0, la constante C se conserva simbólica si P_0, b o k no tienen valor numérico.\", rf\"\\begin{{gathered}}P_0=C-\\frac{{b}}{{k}}\\\\[4px]C=P_0+\\frac{{b}}{{k}}\\\\[4px]\\boxed{{{_latex_igualdad('P', t, expresion)}}}\\end{{gathered}}\"),\n            crear_paso(\"Ítem particular\", \"Si el ejercicio pide la población en un tiempo concreto, se reemplaza solo ese tiempo y los demás parámetros quedan vivos.\", rf\"\\boxed{{{_latex_igualdad('P', tx, expresion_objetivo)}}}\"),\n        ]\n        return _respuesta_formula(\n            modulo=\"crecimiento\",\n            variante=\"entrada_constante\",\n            modelo=\"Crecimiento con entrada constante con parámetros indeterminados\",\n            resultado=f\"P({sp.latex(tx)})={sp.latex(expresion_objetivo)}\" if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"poblacion\") else \"P(t)=(P0+b/k)e^(kt)-b/k\",\n            resultado_latex=_latex_igualdad(\"P\", tx if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"poblacion\") else t, expresion_objetivo if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"poblacion\") else expresion),\n            pasos=pasos,\n        )\n\n    if variante in (\"caida_resistencia\", \"velocidad_limite\"):\n        v0 = _numero_o_simbolo(datos, (\"velocidad_inicial\", \"cantidad_inicial\"), \"v_0\")\n        g = _numero_o_simbolo(datos, (\"gravedad\", \"g\"), \"g\")\n        expresion = g / k + (v0 - g / k) * sp.exp(-k * t)\n        expresion_objetivo = expresion.subs(t, tx)\n        velocidad_limite = g / k\n        pasos = [\n            crear_paso(\"Identificación del modelo\", \"La gravedad actúa como entrada constante y la resistencia resta velocidad proporcionalmente.\", r\"\\frac{dv}{dt}=g-kv\"),\n            crear_paso(\"Solución simbólica\", \"Aunque no se conozca k, la fórmula queda planteada y lista para sustituir datos cuando aparezcan.\", r\"\\begin{gathered}\\frac{dv}{dt}+kv=g\\\\[4px]v(t)=\\frac{g}{k}+Ce^{-kt}\\end{gathered}\"),\n            crear_paso(\"Condición inicial\", \"Con v(0)=v_0 se obtiene la constante de integración sin necesidad de valor numérico.\", rf\"\\begin{{gathered}}v_0=\\frac{{g}}{{k}}+C\\\\[4px]C=v_0-\\frac{{g}}{{k}}\\\\[4px]\\boxed{{{_latex_igualdad('v', t, expresion)}}}\\end{{gathered}}\"),\n            crear_paso(\"Velocidad límite\", \"Si el ítem solo pide la velocidad límite, no se necesita tiempo ni velocidad inicial.\", rf\"\\boxed{{v_\\infty=\\lim_{{t\\to\\infty}}v(t)={sp.latex(velocidad_limite)}}}\"),\n            crear_paso(\"Ítem particular\", \"Si se entrega un tiempo pero falta k, queda una velocidad simbólica evaluada en ese tiempo.\", rf\"\\boxed{{{_latex_igualdad('v', tx, expresion_objetivo)}}}\"),\n        ]\n        es_limite = tipo_calculo in (\"velocidad_limite\", \"limite\", \"equilibrio\")\n        return _respuesta_formula(\n            modulo=\"crecimiento\",\n            variante=\"caida_resistencia\",\n            modelo=\"Caída con resistencia del aire con parámetros indeterminados\",\n            resultado=f\"v∞={sp.latex(velocidad_limite)}\" if es_limite else f\"v({sp.latex(tx)})={sp.latex(expresion_objetivo)}\",\n            resultado_latex=rf\"v_\\infty={sp.latex(velocidad_limite)}\" if es_limite else _latex_igualdad(\"v\", tx, expresion_objetivo),\n            pasos=pasos,\n        )\n\n    if variante in (\"interes_continuo\", \"interes_compuesto_continuo\"):\n        s0 = _numero_o_simbolo(datos, (\"capital_inicial\", \"cantidad_inicial\"), \"S_0\")\n        # Si llega tasa_porcentual, se conserva como r simbólica en el documento; el cálculo numérico lo hace el módulo principal.\n        r = _numero_o_simbolo(datos, (\"constante_k\", \"k\", \"tasa\", \"tasa_porcentual\"), \"r\")\n        expresion = s0 * sp.exp(r * t)\n        expresion_objetivo = expresion.subs(t, tx)\n        pasos = [\n            crear_paso(\"Modelo\", \"El capital crece proporcionalmente al capital presente.\", r\"\\frac{dS}{dt}=rS\"),\n            crear_paso(\"Separación e integración\", \"Se integra sin obligar a conocer numéricamente la tasa.\", r\"\\begin{gathered}\\frac{dS}{S}=r\\,dt\\\\[4px]\\ln|S|=rt+C_1\\end{gathered}\"),\n            crear_paso(\"Fórmula simbólica\", \"Con S(0)=S_0 queda el modelo continuo.\", rf\"\\boxed{{{_latex_igualdad('S', t, expresion)}}}\"),\n            crear_paso(\"Ítem particular\", \"Si el enunciado da una tasa en porcentaje, se usa r=i/100 antes de evaluar.\", rf\"\\boxed{{{_latex_igualdad('S', tx, expresion_objetivo)}}}\"),\n        ]\n        return _respuesta_formula(modulo=\"crecimiento\", variante=\"interes_continuo\", modelo=\"Interés continuo simbólico\", resultado=f\"S({sp.latex(tx)})={sp.latex(expresion_objetivo)}\", resultado_latex=_latex_igualdad(\"S\", tx, expresion_objetivo), pasos=pasos)\n\n    p0 = _numero_o_simbolo(datos, (\"cantidad_inicial\", \"poblacion_inicial\"), \"P_0\")\n    expresion = p0 * sp.exp(k * t)\n    expresion_objetivo = expresion.subs(t, tx)\n    pasos = [\n        crear_paso(\"Modelo proporcional\", \"La razón de cambio es proporcional a la cantidad actual.\", r\"\\frac{dP}{dt}=kP\"),\n        crear_paso(\"Integración manual resumida\", \"Se separan variables y se integra.\", r\"\\begin{gathered}\\frac{dP}{P}=k\\,dt\\\\[4px]\\ln|P|=kt+C_1\\\\[4px]P(t)=Ce^{kt}\\end{gathered}\"),\n        crear_paso(\"Condición inicial simbólica\", \"Con P(0)=P_0, la constante C se mantiene como P_0 si no hay dato numérico.\", rf\"\\boxed{{{_latex_igualdad('P', t, expresion)}}}\"),\n        crear_paso(\"Fórmula para encontrar k\", \"Si luego aparece una medición P(t_1)=P_1, se despeja k.\", r\"\\boxed{k=\\frac{\\ln(P_1/P_0)}{t_1}}\"),\n        crear_paso(\"Ítem particular\", \"Si solo se pide un tiempo objetivo, se sustituye ese tiempo y k puede quedar indeterminada.\", rf\"\\boxed{{{_latex_igualdad('P', tx, expresion_objetivo)}}}\"),\n    ]\n    return _respuesta_formula(modulo=\"crecimiento\", variante=\"crecimiento_proporcional\", modelo=\"Crecimiento proporcional simbólico\", resultado=f\"P({sp.latex(tx)})={sp.latex(expresion_objetivo)}\", resultado_latex=_latex_igualdad(\"P\", tx, expresion_objetivo), pasos=pasos)\n\n\ndef formula_decaimiento(datos: dict[str, Any]) -> dict[str, Any]:\n    variante = normalizar_texto(datos.get(\"variante\", \"decaimiento_radiactivo\"))\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"formula_simbolica\"))\n    t = sp.Symbol(\"x\", real=True) if variante == \"intensidad_luz\" else sp.Symbol(\"t\", real=True)\n    tx = _simbolo_tiempo(datos, (\"distancia_objetivo\", \"tiempo_objetivo\", \"tiempo\"), \"x_f\" if variante == \"intensidad_luz\" else \"t_f\")\n\n    if variante in (\"descarga_capacitor\", \"capacitor\", \"descarga\"):\n        q0 = _numero_o_simbolo(datos, (\"cantidad_inicial\", \"carga_inicial\"), \"q_0\")\n        qf = _numero_o_simbolo(datos, (\"cantidad_objetivo\", \"carga_objetivo\"), \"q_f\")\n        if _tiene_valor(datos, \"constante_k\", \"k\"):\n            k = _numero_o_simbolo(datos, (\"constante_k\", \"k\"), \"k\")\n            expresion = q0 * sp.exp(-k * t)\n            expresion_objetivo = expresion.subs(t, tx)\n            tiempo_objetivo = sp.log(q0 / qf) / k\n            constante = r\"k\"\n            modelo_latex = r\"\\frac{dq}{dt}=-kq\"\n            resultado_texto = f\"q({sp.latex(tx)})={sp.latex(expresion_objetivo)}\" if tipo_calculo not in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\") else f\"t={sp.latex(tiempo_objetivo)}\"\n            resultado_latex = _latex_igualdad(\"q\", tx, expresion_objetivo) if tipo_calculo not in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\") else rf\"t={sp.latex(tiempo_objetivo)}\"\n        else:\n            resistencia = _numero_o_simbolo(datos, (\"resistencia\", \"R\"), \"R\")\n            capacitancia = _numero_o_simbolo(datos, (\"capacitancia\", \"C\"), \"C\")\n            expresion = q0 * sp.exp(-t / (resistencia * capacitancia))\n            expresion_objetivo = expresion.subs(t, tx)\n            tiempo_objetivo = resistencia * capacitancia * sp.log(q0 / qf)\n            constante = r\"\\frac{1}{RC}\"\n            modelo_latex = r\"\\frac{dq}{dt}=-\\frac{1}{RC}q\"\n            if tipo_calculo not in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\"):\n                resultado_texto = f\"q({sp.latex(tx)})={sp.latex(q0)}e^(-{sp.latex(tx)}/(RC))\"\n                resultado_latex = _latex_igualdad(\"q\", tx, expresion_objetivo)\n            else:\n                resultado_texto = f\"t=RC ln({sp.latex(q0)}/{sp.latex(qf)})\"\n                resultado_latex = rf\"t={sp.latex(tiempo_objetivo)}\"\n        pasos = [\n            crear_paso(\"Modelo de descarga\", \"El enunciado puede dar solo la ecuación y una condición inicial; RC puede quedar indeterminado.\", modelo_latex),\n            crear_paso(\"Solución general\", \"La constante de decaimiento puede escribirse como k o como 1/(RC).\", rf\"q(t)=Ce^{{-({constante})t}}\"),\n            crear_paso(\"Condición inicial\", \"Con q(0)=q_0 se reemplaza la constante de integración.\", rf\"\\boxed{{{_latex_igualdad('q', t, expresion)}}}\"),\n            crear_paso(\"Evaluación simbólica\", \"Aunque no se conozca R, C o k, el tiempo solicitado sí puede sustituirse.\", rf\"\\boxed{{{_latex_igualdad('q', tx, expresion_objetivo)}}}\"),\n            crear_paso(\"Tiempo para una carga objetivo\", \"Si el ítem pide cuándo q(t)=q_f, se despeja t sin inventar RC.\", rf\"\\boxed{{t={sp.latex(tiempo_objetivo)}}}\"),\n        ]\n        return _respuesta_formula(modulo=\"decaimiento\", variante=\"descarga_capacitor\", modelo=\"Descarga de capacitor con RC indeterminado\", resultado=resultado_texto, resultado_latex=resultado_latex, pasos=pasos)\n\n    simbolo = \"I\" if variante == \"intensidad_luz\" else (\"C\" if variante == \"absorcion_medicamento\" else \"A\")\n    y0 = _numero_o_simbolo(datos, (\"cantidad_inicial\", \"intensidad_inicial\"), f\"{simbolo}_0\")\n    yf = _numero_o_simbolo(datos, (\"cantidad_objetivo\", \"intensidad_objetivo\"), f\"{simbolo}_f\")\n    k = _numero_o_simbolo(datos, (\"constante_k\", \"k\"), \"k\")\n    expresion = y0 * sp.exp(-k * t)\n    expresion_objetivo = expresion.subs(t, tx)\n    tiempo_objetivo = sp.log(y0 / yf) / k\n    vida_media = sp.log(2) / k\n    pasos = [\n        crear_paso(\"Modelo de decaimiento\", \"La cantidad disminuye proporcionalmente a la cantidad presente.\", rf\"\\frac{{d{simbolo}}}{{dt}}=-k{simbolo}\"),\n        crear_paso(\"Solución general\", \"Se separan variables y se integra, dejando k indeterminada si no se conoce.\", rf\"\\begin{{gathered}}\\frac{{d{simbolo}}}{{{simbolo}}}=-k\\,dt\\\\[4px]\\ln|{simbolo}|=-kt+C_1\\\\[4px]{simbolo}(t)=Ce^{{-kt}}\\end{{gathered}}\"),\n        crear_paso(\"Condición inicial\", \"Con el dato inicial se obtiene la forma particular simbólica.\", rf\"\\boxed{{{_latex_igualdad(simbolo, t, expresion)}}}\"),\n        crear_paso(\"Evaluación simbólica\", \"Si se da un tiempo o distancia objetivo, se reemplaza ese valor aunque k quede indeterminada.\", rf\"\\boxed{{{_latex_igualdad(simbolo, tx, expresion_objetivo)}}}\"),\n        crear_paso(\"Fórmulas útiles\", \"Sirven cuando el ítem pide vida media o tiempo para una cantidad objetivo sin resolver todo numéricamente.\", rf\"\\boxed{{t_{{1/2}}={sp.latex(vida_media)}}}\\qquad \\boxed{{t={sp.latex(tiempo_objetivo)}}}\"),\n    ]\n    if tipo_calculo in (\"vida_media\", \"semivida\"):\n        resultado = f\"t1/2={sp.latex(vida_media)}\"\n        resultado_latex = rf\"t_{{1/2}}={sp.latex(vida_media)}\"\n    elif tipo_calculo in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\"):\n        resultado = f\"t={sp.latex(tiempo_objetivo)}\"\n        resultado_latex = rf\"t={sp.latex(tiempo_objetivo)}\"\n    else:\n        resultado = f\"{simbolo}({sp.latex(tx)})={sp.latex(expresion_objetivo)}\"\n        resultado_latex = _latex_igualdad(simbolo, tx, expresion_objetivo)\n    return _respuesta_formula(modulo=\"decaimiento\", variante=variante or \"decaimiento_radiactivo\", modelo=\"Decaimiento simbólico\", resultado=resultado, resultado_latex=resultado_latex, pasos=pasos)\n\n\ndef formula_enfriamiento(datos: dict[str, Any]) -> dict[str, Any]:\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"formula_simbolica\"))\n    t = sp.Symbol(\"t\", real=True)\n    tx = _simbolo_tiempo(datos, (\"tiempo_objetivo\", \"tiempo\"), \"t_x\")\n    temperatura_ambiente = _numero_o_simbolo(datos, (\"temperatura_ambiente\", \"Ta\"), \"T_a\")\n    temperatura_inicial = _numero_o_simbolo(datos, (\"temperatura_inicial\", \"T0\"), \"T_0\")\n    temperatura_objetivo = _numero_o_simbolo(datos, (\"temperatura_objetivo\", \"T_objetivo\"), \"T_f\")\n    k = _numero_o_simbolo(datos, (\"constante_k\", \"k\"), \"k\")\n    expresion = temperatura_ambiente + (temperatura_inicial - temperatura_ambiente) * sp.exp(-k * t)\n    expresion_objetivo = expresion.subs(t, tx)\n    tiempo_para_temperatura = -sp.log((temperatura_objetivo - temperatura_ambiente) / (temperatura_inicial - temperatura_ambiente)) / k\n    pasos = [\n        crear_paso(\"Modelo de Newton\", \"El cambio térmico depende de la diferencia entre objeto y ambiente.\", r\"\\frac{dT}{dt}=-k(T-T_a)\"),\n        crear_paso(\"Cambio de variable\", \"Se define U=T-T_a para convertirlo en un decaimiento exponencial.\", r\"\\begin{gathered}U=T-T_a\\\\[4px]\\frac{dU}{dt}=-kU\\\\[4px]U(t)=Ce^{-kt}\\end{gathered}\"),\n        crear_paso(\"Fórmula simbólica\", \"Con T(0)=T_0 queda planteada la ley de Newton.\", rf\"\\boxed{{{_latex_igualdad('T', t, expresion)}}}\"),\n        crear_paso(\"Evaluación simbólica\", \"Si existe un tiempo objetivo, se sustituye sin exigir que k sea numérica.\", rf\"\\boxed{{{_latex_igualdad('T', tx, expresion_objetivo)}}}\"),\n        crear_paso(\"Fórmula para encontrar k\", \"Si luego se conoce T(t_1)=T_1, se despeja la constante sin cambiar el modelo.\", r\"\\boxed{k=-\\frac{1}{t_1}\\ln\\left(\\frac{T_1-T_a}{T_0-T_a}\\right)}\"),\n        crear_paso(\"Tiempo para temperatura objetivo\", \"Si piden cuándo se llega a una temperatura, se despeja t simbólicamente.\", rf\"\\boxed{{t={sp.latex(tiempo_para_temperatura)}}}\"),\n    ]\n    if tipo_calculo in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_temperatura\"):\n        resultado = f\"t={sp.latex(tiempo_para_temperatura)}\"\n        resultado_latex = rf\"t={sp.latex(tiempo_para_temperatura)}\"\n    elif tipo_calculo in (\"equilibrio\", \"limite\"):\n        resultado = f\"lim T(t)={sp.latex(temperatura_ambiente)}\"\n        resultado_latex = rf\"\\lim_{{t\\to\\infty}}T(t)={sp.latex(temperatura_ambiente)}\"\n    else:\n        resultado = f\"T({sp.latex(tx)})={sp.latex(expresion_objetivo)}\"\n        resultado_latex = _latex_igualdad(\"T\", tx, expresion_objetivo)\n    return _respuesta_formula(modulo=\"enfriamiento\", variante=\"newton_constante\", modelo=\"Ley de Newton simbólica\", resultado=resultado, resultado_latex=resultado_latex, pasos=pasos)\n\n\ndef formula_mezclas(datos: dict[str, Any]) -> dict[str, Any]:\n    variante = normalizar_texto(datos.get(\"variante\", \"volumen_constante\"))\n    t = sp.Symbol(\"t\", real=True)\n    a0, v0, re, rs, ce, cs = sp.symbols(\"A_0 V_0 r_e r_s c_e c_s\", positive=True)\n    usa_salida_fija = _tiene_valor(datos, \"concentracion_salida\", \"c_salida\", \"cs\", \"c_out\")\n\n    if variante in (\"volumen_variable\", \"tanque_variable\", \"mezcla_variable\"):\n        volumen = v0 + (re - rs) * t\n        if usa_salida_fija:\n            expresion = a0 + (re * ce - rs * cs) * t\n            concentracion = expresion / volumen\n            pasos = [\n                crear_paso(\"Modelo de mezcla\", \"El volumen cambia y se ingresó una concentración de salida fija.\", r\"\\frac{dA}{dt}=r_ec_e-r_sc_s,\\qquad V(t)=V_0+(r_e-r_s)t\"),\n                crear_paso(\"Integración simbólica\", \"Como entrada y salida de soluto son constantes, A(t) queda lineal.\", rf\"\\boxed{{{_latex_igualdad('A', t, expresion)}}}\"),\n                crear_paso(\"Concentración\", \"La concentración del tanque se calcula dividiendo la cantidad entre el volumen actual.\", rf\"\\boxed{{C(t)={sp.latex(concentracion)}}}\"),\n            ]\n            return _respuesta_formula(\n                modulo=\"mezclas\",\n                variante=\"volumen_variable\",\n                modelo=\"Mezcla con volumen variable y concentración de salida fija simbólica\",\n                resultado=\"A(t)=A0+(re·ce-rs·cs)t\",\n                resultado_latex=_latex_igualdad(\"A\", t, expresion),\n                pasos=pasos,\n            )\n\n        expresion = ce * volumen + (a0 - ce * v0) * (v0 / volumen) ** (rs / (re - rs))\n        pasos = [\n            crear_paso(\"Modelo de mezcla\", \"El volumen cambia porque los caudales de entrada y salida no son iguales.\", r\"\\frac{dA}{dt}=r_ec_e-r_s\\frac{A}{V(t)},\\qquad V(t)=V_0+(r_e-r_s)t\"),\n            crear_paso(\"Solución simbólica\", \"El factor integrante genera una fórmula cerrada para A(t).\", rf\"\\boxed{{{_latex_igualdad('A', t, expresion)}}}\"),\n            crear_paso(\"Concentración\", \"Si el ítem pide concentración, se divide la cantidad de soluto entre el volumen.\", r\"\\boxed{C(t)=\\frac{A(t)}{V(t)}}\"),\n        ]\n        return _respuesta_formula(modulo=\"mezclas\", variante=\"volumen_variable\", modelo=\"Mezcla con volumen variable simbólica\", resultado=\"A(t)=ceV(t)+(A0-ceV0)(V0/V(t))^(rs/(re-rs))\", resultado_latex=_latex_igualdad(\"A\", t, expresion), pasos=pasos)\n\n    v, r = sp.symbols(\"V r\", positive=True)\n    if usa_salida_fija:\n        expresion = a0 + (r * ce - r * cs) * t\n        pasos = [\n            crear_paso(\"Modelo de mezcla\", \"En volumen constante con concentración de salida fija se evalúa entrada menos salida constante.\", r\"\\frac{dA}{dt}=rc_e-rc_s\"),\n            crear_paso(\"Integración simbólica\", \"La cantidad cambia linealmente porque la diferencia de soluto por minuto es constante.\", rf\"\\boxed{{{_latex_igualdad('A', t, expresion)}}}\"),\n            crear_paso(\"Concentración\", \"Si el ítem pide concentración, se divide entre el volumen constante.\", r\"\\boxed{C(t)=\\frac{A(t)}{V}}\"),\n        ]\n        return _respuesta_formula(\n            modulo=\"mezclas\",\n            variante=\"volumen_constante\",\n            modelo=\"Mezcla con volumen constante y concentración de salida fija simbólica\",\n            resultado=\"A(t)=A0+r(ce-cs)t\",\n            resultado_latex=_latex_igualdad(\"A\", t, expresion),\n            pasos=pasos,\n        )\n\n    equilibrio = v * ce\n    expresion = equilibrio + (a0 - equilibrio) * sp.exp(-(r / v) * t)\n    pasos = [\n        crear_paso(\"Modelo de mezcla\", \"En volumen constante se cumple r_e=r_s=r y el volumen no cambia.\", r\"\\frac{dA}{dt}=rc_e-r\\frac{A}{V}\"),\n        crear_paso(\"Equilibrio\", \"El equilibrio ocurre cuando entrada y salida de soluto se compensan.\", r\"0=rc_e-r\\frac{A_{\\infty}}{V}\\quad\\Rightarrow\\quad A_{\\infty}=Vc_e\"),\n        crear_paso(\"Fórmula simbólica\", \"La solución se expresa alrededor del equilibrio.\", rf\"\\boxed{{{_latex_igualdad('A', t, expresion)}}}\"),\n        crear_paso(\"Límite\", \"Si el ítem pide el límite, no hace falta evaluar tiempos.\", r\"\\boxed{\\lim_{t\\to\\infty}A(t)=Vc_e}\"),\n    ]\n    return _respuesta_formula(modulo=\"mezclas\", variante=\"volumen_constante\", modelo=\"Mezcla con volumen constante simbólica\", resultado=\"A(t)=Vce+(A0-Vce)e^(-(r/V)t)\", resultado_latex=_latex_igualdad(\"A\", t, expresion), pasos=pasos)",
    "formatoRespuesta": "def crear_respuesta_modelo(\n    *,\n    modulo: str,\n    variante: str,\n    modelo: str,\n    tipo: str,\n    resultado: float | str | None,\n    unidad: str = \"\",\n    resultado_latex: str | None = None,\n    constantes: dict[str, float | str] | None = None,\n    pasos: list[dict[str, str]] | None = None,\n    advertencias: list[str] | None = None,\n    metadatos: dict[str, float | str] | None = None,\n) -> dict:\n    \"\"\"Estandariza la respuesta de todos los modelos.\"\"\"\n    metadatos_finales = {\n        \"motor_matematico\": \"SymPy\",\n        \"prioridad_modelado\": \"construccion_simbolica_con_sympy\",\n    }\n    metadatos_finales.update(metadatos or {})\n\n    pasos_modelo = pasos or []\n    try:\n        from backend.utils.derivaciones import obtener_pasos_derivacion\n\n        derivacion = obtener_pasos_derivacion(modulo, variante)\n    except Exception:\n        # La respuesta del modelo no debe fallar si el bloque pedagógico opcional\n        # tiene un problema de importación durante un despliegue parcial.\n        derivacion = []\n\n    pasos_finales = derivacion + pasos_modelo\n\n    return {\n        \"modulo\": modulo,\n        \"variante\": variante,\n        \"modelo\": modelo,\n        \"tipo\": tipo,\n        \"resultado\": resultado,\n        \"resultado_latex\": resultado_latex or _crear_latex_resultado_generico(resultado, unidad),\n        \"unidad\": unidad,\n        \"constantes\": constantes or {},\n        \"pasos\": pasos_finales,\n        \"advertencias\": advertencias or [],\n        \"metadatos\": metadatos_finales,\n    }",
    "crearPaso": "def crear_paso(titulo: str, descripcion: str, latex: str) -> dict[str, str]:\n    \"\"\"Crea un bloque homogéneo para mostrar la solución paso a paso.\"\"\"\n    return {\"titulo\": titulo, \"descripcion\": descripcion, \"latex\": latex}",
    "validacionCompleta": "\"\"\"Validaciones de entrada para los modelos de ecuaciones diferenciales.\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any, Iterable\n\n\nclass ErrorValidacion(ValueError):\n    \"\"\"Error controlado para entradas inválidas del usuario.\"\"\"\n\n\ndef crear_respuesta_error(mensaje: str, codigo: str = \"entrada_invalida\") -> dict[str, Any]:\n    return {\"error\": True, \"codigo\": codigo, \"mensaje\": mensaje}\n\n\ndef validar_campo_requerido(datos: dict[str, Any], campo: str) -> None:\n    if campo not in datos or datos[campo] in (None, \"\"):\n        raise ErrorValidacion(f\"El campo '{campo}' es obligatorio.\")\n\n\ndef obtener_valor(datos: dict[str, Any], posibles_campos: Iterable[str], nombre: str) -> Any:\n    for campo in posibles_campos:\n        if campo in datos and datos[campo] not in (None, \"\"):\n            return datos[campo]\n    raise ErrorValidacion(f\"Falta el valor requerido: {nombre}.\")\n\n\ndef validar_numero(valor: Any, nombre: str) -> float:\n    try:\n        numero = float(str(valor).replace(\",\", \".\"))\n    except (TypeError, ValueError) as exc:\n        raise ErrorValidacion(f\"{nombre} debe ser un número válido.\") from exc\n    return numero\n\n\ndef validar_positivo(valor: Any, nombre: str) -> float:\n    numero = validar_numero(valor, nombre)\n    if numero <= 0:\n        raise ErrorValidacion(f\"{nombre} debe ser mayor que cero.\")\n    return numero\n\n\ndef validar_no_negativo(valor: Any, nombre: str) -> float:\n    numero = validar_numero(valor, nombre)\n    if numero < 0:\n        raise ErrorValidacion(f\"{nombre} no puede ser negativo.\")\n    return numero\n\n\ndef normalizar_texto(valor: Any) -> str:\n    return str(valor or \"\").strip().lower().replace(\" \", \"_\").replace(\"-\", \"_\")",
    "appFlask": "\"\"\"Aplicación Flask para modelos de ecuaciones diferenciales desplegable en Render.\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nfrom flask import Flask, render_template\nfrom backend.routes.crecimiento_routes import crecimiento_bp\nfrom backend.routes.decaimiento_routes import decaimiento_bp\nfrom backend.routes.enfriamiento_routes import enfriamiento_bp\nfrom backend.routes.mezclas_routes import mezclas_bp\n\nBASE_DIR = Path(__file__).resolve().parent.parent\nTEMPLATE_DIR = BASE_DIR / \"frontend\" / \"templates\"\nSTATIC_DIR = BASE_DIR / \"frontend\" / \"static\"\n\n\ndef crear_app() -> Flask:\n    \"\"\"Crea la aplicación usando rutas relativas compatibles con Render.\"\"\"\n    app = Flask(\n        __name__,\n        template_folder=str(TEMPLATE_DIR),\n        static_folder=str(STATIC_DIR),\n    )\n    @app.get(\"/\")\n    def inicio():\n        return render_template(\"index.html\")\n\n    @app.get(\"/salud\")\n    def salud():\n        return {\n            \"estado\": \"ok\",\n            \"modo\": \"produccion_render\",\n            \"modulos\": [\"crecimiento\", \"decaimiento\", \"enfriamiento\", \"mezclas\", \"python\", \"sympy\", \"autorizacion\"],\n            \"objetivo\": \"montar modelos y variantes, incluir fórmulas simbólicas con datos incompletos y documentación técnica\",\n        }, 200\n\n    app.register_blueprint(crecimiento_bp)\n    app.register_blueprint(decaimiento_bp)\n    app.register_blueprint(enfriamiento_bp)\n    app.register_blueprint(mezclas_bp)\n\n    return app\n\n\napp = crear_app()\n\n\nif __name__ == \"__main__\":\n    import os\n    puerto = int(os.environ.get(\"PORT\", \"5000\"))\n    app.run(host=\"0.0.0.0\", port=puerto, debug=False)\n",
    "rutaCrecimiento": "from flask import Blueprint, request\n\nfrom backend.modelos.crecimiento import resolver_crecimiento\nfrom backend.utils.respuesta import responder_modelo\n\ncrecimiento_bp = Blueprint(\"crecimiento\", __name__, url_prefix=\"/resolver\")\n\n\n@crecimiento_bp.post(\"/crecimiento\")\ndef resolver():\n    return responder_modelo(resolver_crecimiento(request.get_json(silent=True) or {}))",
    "rutaDecaimiento": "from flask import Blueprint, request\n\nfrom backend.modelos.decaimiento import resolver_decaimiento\nfrom backend.utils.respuesta import responder_modelo\n\ndecaimiento_bp = Blueprint(\"decaimiento\", __name__, url_prefix=\"/resolver\")\n\n\n@decaimiento_bp.post(\"/decaimiento\")\ndef resolver():\n    return responder_modelo(resolver_decaimiento(request.get_json(silent=True) or {}))",
    "rutaEnfriamiento": "from flask import Blueprint, request\n\nfrom backend.modelos.enfriamiento import resolver_enfriamiento\nfrom backend.utils.respuesta import responder_modelo\n\nenfriamiento_bp = Blueprint(\"enfriamiento\", __name__, url_prefix=\"/resolver\")\n\n\n@enfriamiento_bp.post(\"/enfriamiento\")\ndef resolver():\n    return responder_modelo(resolver_enfriamiento(request.get_json(silent=True) or {}))",
    "rutaMezclas": "from flask import Blueprint, request\n\nfrom backend.modelos.mezclas import resolver_mezclas\nfrom backend.utils.respuesta import responder_modelo\n\nmezclas_bp = Blueprint(\"mezclas\", __name__, url_prefix=\"/resolver\")\n\n\n@mezclas_bp.post(\"/mezclas\")\ndef resolver():\n    return responder_modelo(resolver_mezclas(request.get_json(silent=True) or {}))",
    "constanteCrecimiento": "def _obtener_constante_crecimiento(\n    datos: dict[str, Any],\n    cantidad_inicial: float,\n) -> tuple[float | None, list[dict[str, str]]]:\n    \"\"\"Obtiene k directamente, la infiere o devuelve None si debe quedar simbólica.\"\"\"\n    pasos: list[dict[str, str]] = []\n\n    if _hay_valor(datos, \"constante_k\", \"k\"):\n        constante_k = validar_positivo(obtener_valor(datos, (\"constante_k\", \"k\"), \"constante k\"), \"Constante k\")\n        pasos.append(crear_paso(\n            \"Constante entregada\",\n            \"La constante de proporcionalidad fue ingresada directamente.\",\n            rf\"\\boxed{{k={formatear_numero(constante_k, DECIMALES_CONSTANTE)}}}\",\n        ))\n        return constante_k, pasos\n\n    if not (_hay_valor(datos, \"tiempo_transcurrido\", \"tiempo_conocido\") and _hay_valor(datos, \"cantidad_transcurrida\", \"cantidad_conocida\")):\n        pasos.append(crear_paso(\n            \"Constante k no entregada\",\n            \"No se fuerza un valor inventado: k queda como parámetro simbólico del modelo.\",\n            r\"\\boxed{k\\;\\text{indeterminada}}\",\n        ))\n        return None, pasos\n\n    tiempo_conocido = validar_positivo(\n        obtener_valor(datos, (\"tiempo_transcurrido\", \"tiempo_conocido\"), \"tiempo conocido\"),\n        \"Tiempo conocido\",\n    )\n    cantidad_conocida = validar_positivo(\n        obtener_valor(datos, (\"cantidad_transcurrida\", \"cantidad_conocida\"), \"cantidad conocida\"),\n        \"Cantidad conocida\",\n    )\n    if cantidad_conocida <= cantidad_inicial:\n        raise ErrorValidacion(\"Para crecimiento proporcional, la cantidad conocida debe ser mayor que la inicial.\")\n\n    constante_k = log(cantidad_conocida / cantidad_inicial) / tiempo_conocido\n    p0 = formatear_numero(cantidad_inicial)\n    p1 = formatear_numero(cantidad_conocida)\n    t1 = formatear_numero(tiempo_conocido)\n    k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n    pasos.append(crear_paso(\n        \"Inferencia de k\",\n        \"Como no se ingresó k, se calcula usando una observación posterior.\",\n        rf\"\\begin{{gathered}}\"\n        rf\"P({t1})={p1},\\quad P(0)={p0}\\\\[6px]\"\n        rf\"{p1}={p0}e^{{k({t1})}}\\\\[6px]\"\n        rf\"k=\\frac{{\\ln\\left(\\frac{{{p1}}}{{{p0}}}\\right)}}{{{t1}}}\\\\[6px]\"\n        rf\"\\boxed{{k={k}}}\"\n        rf\"\\end{{gathered}}\",\n    ))\n    return constante_k, pasos",
    "resolverExponencialBase": "def _resolver_exponencial_base(datos: dict[str, Any], variante: str, etiqueta: str, simbolo: str = \"P\") -> dict[str, Any]:\n    \"\"\"Evalúa modelos de la forma y' = ky; si k falta, responde simbólicamente.\"\"\"\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"valor_en_tiempo\"))\n    if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n        return _respuesta_simbolica(datos, variante)\n\n    if not _hay_valor(datos, \"cantidad_inicial\", \"capital_inicial\", \"poblacion_inicial\"):\n        return _respuesta_simbolica(datos, variante)\n\n    cantidad_inicial = validar_positivo(\n        obtener_valor(datos, (\"cantidad_inicial\", \"capital_inicial\", \"poblacion_inicial\"), \"cantidad inicial\"),\n        \"Cantidad inicial\",\n    )\n    constante_k, pasos_constante = _obtener_constante_crecimiento(datos, cantidad_inicial)\n    if constante_k is None:\n        return _respuesta_simbolica(datos, variante)\n\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = expresion_crecimiento_exponencial(cantidad_inicial, constante_k, variable_t)\n    y0 = formatear_numero(cantidad_inicial)\n    k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n    pasos = [\n        crear_paso(\n            \"Modelo diferencial\",\n            \"La razón de cambio es proporcional a la cantidad presente.\",\n            rf\"\\frac{{d{simbolo}}}{{dt}}=k{simbolo}\",\n        ),\n        crear_paso(\n            \"Solución general del modelo\",\n            \"Se separan variables, se integra y se obtiene el modelo exponencial.\",\n            rf\"\\begin{{gathered}}\"\n            rf\"\\frac{{d{simbolo}}}{{{simbolo}}}=k\\,dt\\\\[6px]\"\n            rf\"\\int \\frac{{d{simbolo}}}{{{simbolo}}}=\\int k\\,dt\\\\[6px]\"\n            rf\"\\ln|{simbolo}|=kt+C_1\\\\[6px]\"\n            rf\"\\boxed{{{simbolo}(t)=Ce^{{kt}}}}\"\n            rf\"\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Condición inicial\",\n            \"Al evaluar en t=0, la constante C queda igual a la cantidad inicial.\",\n            rf\"\\begin{{gathered}}{simbolo}(0)=Ce^{{0}}=C\\\\[6px]\\boxed{{C={y0}}}\\end{{gathered}}\",\n        ),\n        *pasos_constante,\n        crear_paso(\n            \"Función particular\",\n            \"Se reemplazan C y k en la solución general.\",\n            rf\"\\boxed{{{simbolo}(t)={y0}e^{{{k}t}}}}\",\n        ),\n        crear_paso(\n            \"Chequeo simbólico con SymPy\",\n            \"Antes de evaluar, la función se representa simbólicamente para conservar una salida LaTeX limpia.\",\n            paso_sympy(simbolo, variable_t, expresion_sympy),\n        ),\n    ]\n\n    constantes = {\"k\": redondear(constante_k, DECIMALES_CONSTANTE), \"C\": redondear(cantidad_inicial)}\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=variante,\n            modelo=etiqueta,\n            tipo=\"funcion\",\n            resultado=f\"{simbolo}(t)={y0}e^({k}t)\",\n            unidad=\"función\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"poblacion\", \"monto\"):\n        if not _hay_valor(datos, \"tiempo_objetivo\", \"tiempo\"):\n            return _respuesta_simbolica(datos, variante)\n        tiempo_objetivo = validar_no_negativo(\n            obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"),\n            \"Tiempo objetivo\",\n        )\n        valor = evaluar(expresion_sympy, variable_t, tiempo_objetivo)\n        tx = formatear_numero(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Evaluación del modelo\",\n            \"Se evalúa la función particular en el tiempo solicitado.\",\n            rf\"\\begin{{gathered}}{simbolo}({tx})={y0}e^{{{k}({tx})}}\\\\[6px]\"\n            rf\"\\boxed{{{simbolo}({tx})\\approx {formatear_numero(valor)}}}\\end{{gathered}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=variante,\n            modelo=etiqueta,\n            tipo=\"valor_en_tiempo\",\n            resultado=redondear(valor),\n            unidad=datos.get(\"unidad\", \"unidades\"),\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\"):\n        if not _hay_valor(datos, \"cantidad_objetivo\", \"poblacion_objetivo\", \"monto_objetivo\"):\n            return _respuesta_simbolica(datos, variante)\n        cantidad_objetivo = validar_positivo(\n            obtener_valor(datos, (\"cantidad_objetivo\", \"poblacion_objetivo\", \"monto_objetivo\"), \"cantidad objetivo\"),\n            \"Cantidad objetivo\",\n        )\n        if cantidad_objetivo < cantidad_inicial:\n            raise ErrorValidacion(\"En crecimiento proporcional, la cantidad objetivo debe ser mayor o igual que la inicial.\")\n        tiempo = log(cantidad_objetivo / cantidad_inicial) / constante_k\n        objetivo = formatear_numero(cantidad_objetivo)\n        pasos.append(crear_paso(\n            \"Tiempo para alcanzar una cantidad\",\n            \"Se despeja t aplicando logaritmo natural.\",\n            rf\"\\begin{{gathered}}{objetivo}={y0}e^{{{k}t}}\\\\[6px]\"\n            rf\"t=\\frac{{\\ln\\left(\\frac{{{objetivo}}}{{{y0}}}\\right)}}{{{k}}}\\\\[6px]\"\n            rf\"\\boxed{{t\\approx {formatear_numero(tiempo)}}}\\end{{gathered}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=variante,\n            modelo=etiqueta,\n            tipo=\"tiempo_objetivo\",\n            resultado=redondear(tiempo),\n            unidad=\"unidades de tiempo\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para la variante exponencial de crecimiento.\")",
    "resolverInteresContinuo": "def _resolver_interes_continuo(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Evalúa S' = rS usando tasa continua anual. La tasa puede quedar simbólica.\"\"\"\n    datos_normalizados = dict(datos)\n    if not _hay_valor(datos_normalizados, \"constante_k\", \"k\"):\n        if _hay_valor(datos_normalizados, \"tasa_porcentual\", \"tasa\"):\n            tasa_porcentual = validar_positivo(\n                obtener_valor(datos_normalizados, (\"tasa_porcentual\", \"tasa\"), \"tasa porcentual\"),\n                \"Tasa porcentual\",\n            )\n            datos_normalizados[\"constante_k\"] = tasa_porcentual / 100\n        else:\n            return _respuesta_simbolica(datos_normalizados, \"interes_continuo\")\n    datos_normalizados.setdefault(\"unidad\", \"dinero\")\n    return _resolver_exponencial_base(\n        datos_normalizados,\n        variante=\"interes_continuo\",\n        etiqueta=\"Interés compuesto continuo: S'=rS\",\n        simbolo=\"S\",\n    )",
    "resolverEntradaConstante": "def _resolver_entrada_constante(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Evalúa P' = kP + b. Si k no llega, muestra la fórmula simbólica.\"\"\"\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"valor_en_tiempo\"))\n    if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n        return _respuesta_simbolica(datos, \"entrada_constante\")\n    if not (_hay_valor(datos, \"cantidad_inicial\", \"poblacion_inicial\") and _hay_valor(datos, \"constante_k\", \"k\") and _hay_valor(datos, \"entrada_constante\", \"b\")):\n        return _respuesta_simbolica(datos, \"entrada_constante\")\n\n    cantidad_inicial = validar_positivo(obtener_valor(datos, (\"cantidad_inicial\", \"poblacion_inicial\"), \"cantidad inicial\"), \"Cantidad inicial\")\n    constante_k = validar_positivo(obtener_valor(datos, (\"constante_k\", \"k\"), \"constante k\"), \"Constante k\")\n    entrada_constante = validar_no_negativo(obtener_valor(datos, (\"entrada_constante\", \"b\"), \"entrada constante\"), \"Entrada constante\")\n\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = expresion_crecimiento_entrada_constante(cantidad_inicial, constante_k, entrada_constante, variable_t)\n    p0 = formatear_numero(cantidad_inicial)\n    k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n    b = formatear_numero(entrada_constante)\n    equilibrio = -entrada_constante / constante_k\n\n    def funcion(tiempo: float) -> float:\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    pasos = [\n        crear_paso(\"Modelo diferencial\", \"La población crece proporcionalmente y además recibe una entrada constante.\", r\"\\frac{dP}{dt}=kP+b\"),\n        crear_paso(\"Solución general\", \"Es una EDO lineal de primer orden con término independiente constante.\", r\"\\begin{gathered}\\frac{dP}{dt}-kP=b\\\\[6px]P(t)=Ce^{kt}-\\frac{b}{k}\\end{gathered}\"),\n        crear_paso(\"Condición inicial\", \"Se aplica P(0)=P0 para calcular C.\", rf\"\\begin{{gathered}}{p0}=C-\\frac{{{b}}}{{{k}}}\\\\[6px]\\boxed{{C={formatear_numero(cantidad_inicial + entrada_constante / constante_k)}}}\\end{{gathered}}\"),\n        crear_paso(\"Función particular\", \"Se sustituyen los parámetros del modelo.\", rf\"\\boxed{{P(t)=\\left({p0}+\\frac{{{b}}}{{{k}}}\\right)e^{{{k}t}}-\\frac{{{b}}}{{{k}}}}}\"),\n        crear_paso(\"Chequeo simbólico con SymPy\", \"La variante lineal se deja como expresión simbólica y luego se evalúa numéricamente.\", paso_sympy(\"P\", variable_t, expresion_sympy)),\n    ]\n\n    constantes = {\n        \"k\": redondear(constante_k, DECIMALES_CONSTANTE),\n        \"b\": redondear(entrada_constante),\n        \"C\": redondear(cantidad_inicial + entrada_constante / constante_k),\n        \"equilibrio_matematico\": redondear(equilibrio),\n    }\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(modulo=MODULO, variante=\"entrada_constante\", modelo=\"Crecimiento con entrada constante: P'=kP+b\", tipo=\"funcion\", resultado=f\"P(t)=({p0}+{b}/{k})e^({k}t)-{b}/{k}\", unidad=\"función\", constantes=constantes, pasos=pasos)\n\n    if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"poblacion\"):\n        if not _hay_valor(datos, \"tiempo_objetivo\", \"tiempo\"):\n            return _respuesta_simbolica(datos, \"entrada_constante\")\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = funcion(tiempo_objetivo)\n        pasos.append(crear_paso(\"Evaluación del modelo\", \"Se reemplaza el tiempo solicitado en la función particular.\", rf\"\\boxed{{P({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\"))\n        return crear_respuesta_modelo(modulo=MODULO, variante=\"entrada_constante\", modelo=\"Crecimiento con entrada constante: P'=kP+b\", tipo=\"valor_en_tiempo\", resultado=redondear(valor), unidad=datos.get(\"unidad\", \"individuos\"), constantes=constantes, pasos=pasos)\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para crecimiento con entrada constante.\")",
    "resolverCaidaResistencia": "def _resolver_caida_resistencia(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Evalúa v' = g - kv. Si k falta, deja v(t) y v∞ simbólicas.\"\"\"\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"valor_en_tiempo\"))\n    if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n        return _respuesta_simbolica(datos, \"caida_resistencia\")\n    if not (_hay_valor(datos, \"velocidad_inicial\", \"cantidad_inicial\") and _hay_valor(datos, \"gravedad\", \"g\") and _hay_valor(datos, \"constante_k\", \"k\")):\n        return _respuesta_simbolica(datos, \"caida_resistencia\")\n\n    velocidad_inicial = validar_no_negativo(obtener_valor(datos, (\"velocidad_inicial\", \"cantidad_inicial\"), \"velocidad inicial\"), \"Velocidad inicial\")\n    gravedad = validar_positivo(obtener_valor(datos, (\"gravedad\", \"g\"), \"gravedad\"), \"Gravedad\")\n    constante_k = validar_positivo(obtener_valor(datos, (\"constante_k\", \"k\"), \"constante k\"), \"Constante k\")\n    velocidad_limite = gravedad / constante_k\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = expresion_caida_resistencia(velocidad_inicial, gravedad, constante_k, variable_t)\n\n    v0 = formatear_numero(velocidad_inicial)\n    g = formatear_numero(gravedad)\n    k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n    vl = formatear_numero(velocidad_limite)\n\n    def funcion(tiempo: float) -> float:\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    pasos = [\n        crear_paso(\"Modelo diferencial\", \"La aceleración disminuye por una resistencia proporcional a la velocidad.\", r\"\\frac{dv}{dt}=g-kv\"),\n        crear_paso(\"Solución general\", \"Es una EDO lineal con equilibrio en la velocidad límite.\", r\"\\begin{gathered}\\frac{dv}{dt}+kv=g\\\\[6px]v(t)=\\frac{g}{k}+Ce^{-kt}\\end{gathered}\"),\n        crear_paso(\"Condición inicial\", \"Se aplica v(0)=v0 para encontrar C.\", rf\"\\begin{{gathered}}{v0}=\\frac{{{g}}}{{{k}}}+C\\\\[6px]\\boxed{{C={formatear_numero(velocidad_inicial - velocidad_limite)}}}\\end{{gathered}}\"),\n        crear_paso(\"Función particular\", \"Se reemplazan los parámetros en el modelo de velocidad.\", rf\"\\boxed{{v(t)={vl}+({v0}-{vl})e^{{-{k}t}}}}\"),\n        crear_paso(\"Chequeo simbólico con SymPy\", \"SymPy conserva la forma simbólica de la velocidad antes de evaluar o tomar el límite.\", paso_sympy(\"v\", variable_t, expresion_sympy)),\n    ]\n\n    constantes = {\"g\": redondear(gravedad), \"k\": redondear(constante_k, DECIMALES_CONSTANTE), \"velocidad_limite\": redondear(velocidad_limite)}\n\n    if tipo_calculo in (\"velocidad_limite\", \"limite\", \"equilibrio\"):\n        pasos.append(crear_paso(\"Velocidad límite\", \"Cuando t tiende a infinito, el término exponencial desaparece.\", rf\"\\lim_{{t\\to\\infty}}v(t)=\\frac{{g}}{{k}}=\\boxed{{{vl}}}\"))\n        return crear_respuesta_modelo(modulo=MODULO, variante=\"caida_resistencia\", modelo=\"Caída con resistencia del aire: v'=g-kv\", tipo=\"velocidad_limite\", resultado=redondear(velocidad_limite), unidad=\"m/s\", constantes=constantes, pasos=pasos)\n\n    if tipo_calculo in (\"valor_en_tiempo\", \"velocidad\"):\n        if not _hay_valor(datos, \"tiempo_objetivo\", \"tiempo\"):\n            return _respuesta_simbolica(datos, \"caida_resistencia\")\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = funcion(tiempo_objetivo)\n        pasos.append(crear_paso(\"Evaluación de velocidad\", \"Se evalúa la función en el tiempo solicitado.\", rf\"\\boxed{{v({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\"))\n        return crear_respuesta_modelo(modulo=MODULO, variante=\"caida_resistencia\", modelo=\"Caída con resistencia del aire: v'=g-kv\", tipo=\"valor_en_tiempo\", resultado=redondear(valor), unidad=\"m/s\", constantes=constantes, pasos=pasos)\n\n    if tipo_calculo in (\"funcion\", \"solucion\"):\n        return crear_respuesta_modelo(modulo=MODULO, variante=\"caida_resistencia\", modelo=\"Caída con resistencia del aire: v'=g-kv\", tipo=\"funcion\", resultado=f\"v(t)={vl}+({v0}-{vl})e^(-{k}t)\", unidad=\"función\", constantes=constantes, pasos=pasos)\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para caída con resistencia del aire.\")",
    "resolverCrecimiento": "def resolver_crecimiento(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Método único del módulo crecimiento que evalúa sus variantes internas.\"\"\"\n    try:\n        variante = normalizar_texto(datos.get(\"variante\", \"crecimiento_proporcional\"))\n        tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"valor_en_tiempo\"))\n        if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n            return formula_crecimiento(datos)\n        if variante in (\"crecimiento_proporcional\", \"poblacional\", \"exp_base\"):\n            return _resolver_exponencial_base(datos, variante=\"crecimiento_proporcional\", etiqueta=\"Crecimiento proporcional: P'=kP\", simbolo=\"P\")\n        if variante in (\"interes_continuo\", \"interes_compuesto_continuo\"):\n            return _resolver_interes_continuo(datos)\n        if variante in (\"entrada_constante\", \"crecimiento_entrada_constante\", \"lineal_entrada\"):\n            return _resolver_entrada_constante(datos)\n        if variante in (\"caida_resistencia\", \"velocidad_limite\"):\n            return _resolver_caida_resistencia(datos)\n        raise ErrorValidacion(f\"Variante no soportada en crecimiento: {variante}.\")\n    except (ErrorValidacion, ValueError, ZeroDivisionError) as error:\n        return crear_respuesta_error(str(error))",
    "constanteDecaimiento": "def _obtener_constante_decaimiento(\n    datos: dict[str, Any],\n    cantidad_inicial: float,\n    variante: str,\n) -> tuple[float | None, list[dict[str, str]]]:\n    \"\"\"Obtiene k directamente, por RC, por medición o la deja indeterminada.\"\"\"\n    pasos: list[dict[str, str]] = []\n\n    if variante == \"descarga_capacitor\" and _hay_valor(datos, \"resistencia\") and _hay_valor(datos, \"capacitancia\"):\n        resistencia = validar_positivo(datos[\"resistencia\"], \"Resistencia\")\n        capacitancia = validar_positivo(datos[\"capacitancia\"], \"Capacitancia\")\n        constante_k = 1 / (resistencia * capacitancia)\n        pasos.append(crear_paso(\n            \"Constante del circuito RC\",\n            \"Para la descarga de capacitor, la constante de decaimiento es 1/(RC).\",\n            rf\"\\boxed{{k=\\frac{{1}}{{RC}}=\\frac{{1}}{{{formatear_numero(resistencia)}\\cdot {formatear_numero(capacitancia)}}}={formatear_numero(constante_k, DECIMALES_CONSTANTE)}}}\",\n        ))\n        return constante_k, pasos\n\n    if _hay_valor(datos, \"constante_k\", \"k\"):\n        constante_k = validar_positivo(obtener_valor(datos, (\"constante_k\", \"k\"), \"constante k\"), \"Constante k\")\n        pasos.append(crear_paso(\n            \"Constante entregada\",\n            \"La constante de decaimiento fue ingresada directamente.\",\n            rf\"\\boxed{{k={formatear_numero(constante_k, DECIMALES_CONSTANTE)}}}\",\n        ))\n        return constante_k, pasos\n\n    if not (_hay_valor(datos, \"tiempo_transcurrido\", \"distancia_transcurrida\", \"tiempo_conocido\") and _hay_valor(datos, \"cantidad_transcurrida\", \"cantidad_restante\", \"cantidad_conocida\")):\n        pasos.append(crear_paso(\n            \"Constante k no entregada\",\n            \"No se conoce k ni existe una medición suficiente para inferirla; por eso se conserva simbólica.\",\n            r\"\\boxed{k\\;\\text{indeterminada}}\",\n        ))\n        return None, pasos\n\n    tiempo_conocido = validar_positivo(obtener_valor(datos, (\"tiempo_transcurrido\", \"distancia_transcurrida\", \"tiempo_conocido\"), \"tiempo o distancia conocida\"), \"Tiempo o distancia conocida\")\n    cantidad_conocida = validar_positivo(obtener_valor(datos, (\"cantidad_transcurrida\", \"cantidad_restante\", \"cantidad_conocida\"), \"cantidad restante\"), \"Cantidad restante\")\n    if cantidad_conocida >= cantidad_inicial:\n        raise ErrorValidacion(\"En decaimiento, la cantidad conocida debe ser menor que la cantidad inicial.\")\n\n    constante_k = log(cantidad_inicial / cantidad_conocida) / tiempo_conocido\n    y0 = formatear_numero(cantidad_inicial)\n    y1 = formatear_numero(cantidad_conocida)\n    t1 = formatear_numero(tiempo_conocido)\n    k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n    pasos.append(crear_paso(\n        \"Inferencia de k\",\n        \"Como no se ingresó k, se calcula con una medición posterior.\",\n        rf\"\\begin{{gathered}}\"\n        rf\"Y({t1})={y1},\\quad Y(0)={y0}\\\\[6px]\"\n        rf\"{y1}={y0}e^{{-k({t1})}}\\\\[6px]\"\n        rf\"k=\\frac{{\\ln\\left(\\frac{{{y0}}}{{{y1}}}\\right)}}{{{t1}}}\\\\[6px]\"\n        rf\"\\boxed{{k={k}}}\"\n        rf\"\\end{{gathered}}\",\n    ))\n    return constante_k, pasos",
    "resolverDecaimientoCompleto": "def resolver_decaimiento(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Método único del módulo decaimiento que evalúa sus variantes internas.\"\"\"\n    try:\n        variante = _normalizar_variante(datos.get(\"variante\", \"decaimiento_radiactivo\"))\n        if variante not in CONFIG_VARIANTES:\n            raise ErrorValidacion(f\"Variante no soportada en decaimiento: {variante}.\")\n\n        config = CONFIG_VARIANTES[variante]\n        simbolo = config[\"simbolo\"]\n        tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"valor_en_tiempo\"))\n        if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n            return formula_decaimiento({**datos, \"variante\": variante})\n        if not _hay_valor(datos, \"cantidad_inicial\", \"carga_inicial\", \"intensidad_inicial\"):\n            return formula_decaimiento({**datos, \"variante\": variante})\n        cantidad_inicial = validar_positivo(obtener_valor(datos, (\"cantidad_inicial\", \"carga_inicial\", \"intensidad_inicial\"), \"cantidad inicial\"), \"Cantidad inicial\")\n        constante_k, pasos_constante = _obtener_constante_decaimiento(datos, cantidad_inicial, variante)\n        if constante_k is None:\n            return formula_decaimiento({**datos, \"variante\": variante})\n\n        variable_t = crear_variable(\"x\" if variante == \"intensidad_luz\" else \"t\")\n        expresion_sympy = expresion_decaimiento_exponencial(cantidad_inicial, constante_k, variable_t)\n        y0 = formatear_numero(cantidad_inicial)\n        k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n        vida_media = log(2) / constante_k\n\n        pasos = [\n            crear_paso(\n                \"Modelo diferencial\",\n                config[\"descripcion\"],\n                rf\"\\frac{{d{simbolo}}}{{dt}}=-k{simbolo}\",\n            ),\n            crear_paso(\n                \"Solución general\",\n                \"Se separan variables, se integra y se obtiene una exponencial decreciente.\",\n                rf\"\\begin{{gathered}}\"\n                rf\"\\frac{{d{simbolo}}}{{{simbolo}}}=-k\\,dt\\\\[6px]\"\n                rf\"\\int\\frac{{d{simbolo}}}{{{simbolo}}}=\\int -k\\,dt\\\\[6px]\"\n                rf\"\\ln|{simbolo}|=-kt+C_1\\\\[6px]\"\n                rf\"\\boxed{{{simbolo}(t)=Ce^{{-kt}}}}\"\n                rf\"\\end{{gathered}}\",\n            ),\n            crear_paso(\n                \"Condición inicial\",\n                \"Al evaluar en t=0, la constante C corresponde a la cantidad inicial.\",\n                rf\"\\begin{{gathered}}{simbolo}(0)=Ce^0=C\\\\[6px]\\boxed{{C={y0}}}\\end{{gathered}}\",\n            ),\n            *pasos_constante,\n            crear_paso(\n                \"Función particular\",\n                \"Se reemplazan C y k en la solución del modelo.\",\n                rf\"\\boxed{{{simbolo}({str(variable_t)})={y0}e^{{-{k}{str(variable_t)}}}}}\",\n            ),\n            crear_paso(\n                \"Chequeo simbólico con SymPy\",\n                \"La expresión se conserva simbólicamente para evaluar tiempo, distancia, vida media o función.\",\n                paso_sympy(simbolo, variable_t, expresion_sympy),\n            ),\n        ]\n\n        constantes = {\"k\": redondear(constante_k, DECIMALES_CONSTANTE), \"C\": redondear(cantidad_inicial), \"vida_media\": redondear(vida_media)}\n\n        if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=variante,\n                modelo=config[\"modelo\"],\n                tipo=\"funcion\",\n                resultado=f\"{simbolo}(t)={y0}e^(-{k}t)\",\n                unidad=\"función\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"valor_en_tiempo\", \"cantidad\", \"carga\", \"intensidad\"):\n            if not _hay_valor(datos, \"tiempo_objetivo\", \"distancia_objetivo\", \"tiempo\"):\n                return formula_decaimiento({**datos, \"variante\": variante})\n            tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"distancia_objetivo\", \"tiempo\"), \"tiempo o distancia objetivo\"), \"Tiempo o distancia objetivo\")\n            valor = evaluar(expresion_sympy, variable_t, tiempo_objetivo)\n            pasos.append(crear_paso(\n                \"Evaluación del modelo\",\n                \"Se evalúa la función particular en el tiempo o distancia solicitada.\",\n                rf\"\\begin{{gathered}}{simbolo}({formatear_numero(tiempo_objetivo)})={y0}e^{{-{k}({formatear_numero(tiempo_objetivo)})}}\\\\[6px]\"\n                rf\"\\boxed{{{simbolo}({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\\end{{gathered}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=variante,\n                modelo=config[\"modelo\"],\n                tipo=\"valor_en_tiempo\",\n                resultado=redondear(valor),\n                unidad=datos.get(\"unidad\", config[\"unidad\"]),\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_cantidad\"):\n            if not _hay_valor(datos, \"cantidad_objetivo\", \"carga_objetivo\", \"intensidad_objetivo\"):\n                return formula_decaimiento({**datos, \"variante\": variante})\n            cantidad_objetivo = validar_positivo(obtener_valor(datos, (\"cantidad_objetivo\", \"carga_objetivo\", \"intensidad_objetivo\"), \"cantidad objetivo\"), \"Cantidad objetivo\")\n            if cantidad_objetivo >= cantidad_inicial:\n                raise ErrorValidacion(\"En decaimiento, la cantidad objetivo debe ser menor que la cantidad inicial.\")\n            tiempo = log(cantidad_inicial / cantidad_objetivo) / constante_k\n            objetivo = formatear_numero(cantidad_objetivo)\n            pasos.append(crear_paso(\n                \"Tiempo para alcanzar una cantidad\",\n                \"Se despeja t aplicando logaritmo natural.\",\n                rf\"\\begin{{gathered}}{objetivo}={y0}e^{{-{k}t}}\\\\[6px]\"\n                rf\"t=\\frac{{\\ln\\left(\\frac{{{y0}}}{{{objetivo}}}\\right)}}{{{k}}}\\\\[6px]\"\n                rf\"\\boxed{{t\\approx {formatear_numero(tiempo)}}}\\end{{gathered}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=variante,\n                modelo=config[\"modelo\"],\n                tipo=\"tiempo_objetivo\",\n                resultado=redondear(tiempo),\n                unidad=\"unidades de tiempo/distancia\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"vida_media\", \"semivida\"):\n            pasos.append(crear_paso(\n                \"Vida media\",\n                \"La vida media es el tiempo requerido para que quede la mitad de la cantidad inicial.\",\n                rf\"\\begin{{gathered}}\\frac{{{y0}}}{{2}}={y0}e^{{-kt}}\\\\[6px]\"\n                rf\"\\boxed{{t_{{1/2}}=\\frac{{\\ln 2}}{{k}}={formatear_numero(vida_media)}}}\\end{{gathered}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=variante,\n                modelo=config[\"modelo\"],\n                tipo=\"vida_media\",\n                resultado=redondear(vida_media),\n                unidad=\"unidades de tiempo\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        raise ErrorValidacion(\"Tipo de cálculo inválido para decaimiento.\")\n    except (ErrorValidacion, ValueError, ZeroDivisionError) as error:\n        return crear_respuesta_error(str(error))",
    "inferirNewton": "def _inferir_k(temperatura_inicial: float, temperatura_ambiente: float, temperatura_conocida: float, tiempo_conocido: float) -> float:\n    diferencia_inicial = temperatura_inicial - temperatura_ambiente\n    diferencia_conocida = temperatura_conocida - temperatura_ambiente\n\n    if diferencia_inicial == 0:\n        raise ErrorValidacion(\"La temperatura inicial no puede ser igual a la temperatura ambiente.\")\n    if diferencia_inicial * diferencia_conocida <= 0:\n        raise ErrorValidacion(\"La temperatura conocida debe estar del mismo lado de la temperatura ambiente que la inicial.\")\n    if abs(diferencia_conocida) >= abs(diferencia_inicial):\n        raise ErrorValidacion(\"La temperatura debe acercarse a la ambiente; la diferencia conocida debe ser menor.\")\n\n    return -log(diferencia_conocida / diferencia_inicial) / tiempo_conocido",
    "resolverEnfriamientoCompleto": "def resolver_enfriamiento(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Método único del módulo enfriamiento que evalúa variantes de Newton.\"\"\"\n    try:\n        variante = normalizar_texto(datos.get(\"variante\", \"newton_constante\"))\n        if variante not in (\"newton_constante\", \"ley_newton\", \"calentamiento_newton\"):\n            raise ErrorValidacion(f\"Variante no soportada en enfriamiento: {variante}.\")\n\n        tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"temperatura\"))\n        if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n            return formula_enfriamiento(datos)\n        if not (_hay_valor(datos, \"temperatura_inicial\", \"T0\") and _hay_valor(datos, \"temperatura_ambiente\", \"Ta\")):\n            return formula_enfriamiento(datos)\n        temperatura_inicial = validar_numero(obtener_valor(datos, (\"temperatura_inicial\", \"T0\"), \"temperatura inicial\"), \"Temperatura inicial\")\n        temperatura_ambiente = validar_numero(obtener_valor(datos, (\"temperatura_ambiente\", \"Ta\"), \"temperatura ambiente\"), \"Temperatura ambiente\")\n\n        if _hay_valor(datos, \"constante_k\", \"k\"):\n            constante_k = validar_positivo(obtener_valor(datos, (\"constante_k\", \"k\"), \"constante k\"), \"Constante k\")\n            pasos_constante = [crear_paso(\n                \"Constante entregada\",\n                \"La constante de enfriamiento fue ingresada directamente.\",\n                rf\"\\boxed{{k={formatear_numero(constante_k, DECIMALES_CONSTANTE)}}}\",\n            )]\n        else:\n            if not (_hay_valor(datos, \"temperatura_transcurrida\", \"temperatura_conocida\", \"T1\") and _hay_valor(datos, \"tiempo_transcurrido\", \"tiempo_conocido\")):\n                return formula_enfriamiento(datos)\n            temperatura_conocida = validar_numero(obtener_valor(datos, (\"temperatura_transcurrida\", \"temperatura_conocida\", \"T1\"), \"temperatura conocida\"), \"Temperatura conocida\")\n            tiempo_conocido = validar_positivo(obtener_valor(datos, (\"tiempo_transcurrido\", \"tiempo_conocido\"), \"tiempo conocido\"), \"Tiempo conocido\")\n            constante_k = _inferir_k(temperatura_inicial, temperatura_ambiente, temperatura_conocida, tiempo_conocido)\n            pasos_constante = [crear_paso(\n                \"Inferencia de k\",\n                \"Se usa la medición conocida para calcular la constante de Newton.\",\n                rf\"\\begin{{gathered}}\"\n                rf\"T(t)=T_a+(T_0-T_a)e^{{-kt}}\\\\[6px]\"\n                rf\"{formatear_numero(temperatura_conocida)}={formatear_numero(temperatura_ambiente)}+({formatear_numero(temperatura_inicial)}-{formatear_numero(temperatura_ambiente)})e^{{-k({formatear_numero(tiempo_conocido)})}}\\\\[6px]\"\n                rf\"k=-\\frac{{1}}{{{formatear_numero(tiempo_conocido)}}}\\ln\\left(\\frac{{{formatear_numero(temperatura_conocida)}-{formatear_numero(temperatura_ambiente)}}}{{{formatear_numero(temperatura_inicial)}-{formatear_numero(temperatura_ambiente)}}}\\right)\\\\[6px]\"\n                rf\"\\boxed{{k={formatear_numero(constante_k, DECIMALES_CONSTANTE)}}}\"\n                rf\"\\end{{gathered}}\",\n            )]\n\n        t0 = formatear_numero(temperatura_inicial)\n        ta = formatear_numero(temperatura_ambiente)\n        diferencia = formatear_numero(temperatura_inicial - temperatura_ambiente)\n        k = formatear_numero(constante_k, DECIMALES_CONSTANTE)\n        variable_t = crear_variable(\"t\")\n        expresion_sympy = expresion_newton(temperatura_inicial, temperatura_ambiente, constante_k, variable_t)\n\n        def funcion(tiempo: float) -> float:\n            return evaluar(expresion_sympy, variable_t, tiempo)\n\n        pasos = [\n            crear_paso(\n                \"Modelo diferencial\",\n                \"La temperatura cambia proporcionalmente a la diferencia entre el objeto y el ambiente.\",\n                r\"\\frac{dT}{dt}=-k(T-T_a)\",\n            ),\n            crear_paso(\n                \"Solución general\",\n                \"Se desplaza la variable respecto a la temperatura ambiente y se integra.\",\n                r\"\\begin{gathered}U=T-T_a\\\\[6px]\"\n                r\"\\frac{dU}{dt}=-kU\\\\[6px]\"\n                r\"U(t)=Ce^{-kt}\\\\[6px]\"\n                r\"\\boxed{T(t)=T_a+Ce^{-kt}}\\end{gathered}\",\n            ),\n            crear_paso(\n                \"Condición inicial\",\n                \"Con T(0)=T0, la constante C es la diferencia inicial con el ambiente.\",\n                rf\"\\begin{{gathered}}{t0}={ta}+C\\\\[6px]\\boxed{{C={diferencia}}}\\end{{gathered}}\",\n            ),\n            *pasos_constante,\n            crear_paso(\n                \"Función particular\",\n                \"Se reemplazan la temperatura ambiente, la diferencia inicial y k.\",\n                rf\"\\boxed{{T(t)={ta}+({diferencia})e^{{-{k}t}}}}\",\n            ),\n            crear_paso(\n                \"Chequeo simbólico con SymPy\",\n                \"La función de Newton se conserva simbólicamente antes de evaluar temperatura, tiempo o límite.\",\n                paso_sympy(\"T\", variable_t, expresion_sympy),\n            ),\n        ]\n\n        constantes = {\n            \"k\": redondear(constante_k, DECIMALES_CONSTANTE),\n            \"Ta\": redondear(temperatura_ambiente),\n            \"C\": redondear(temperatura_inicial - temperatura_ambiente),\n        }\n\n        if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=\"newton_constante\",\n                modelo=\"Ley de enfriamiento de Newton: T'=-k(T-Ta)\",\n                tipo=\"funcion\",\n                resultado=f\"T(t)={ta}+({diferencia})e^(-{k}t)\",\n                unidad=\"función\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"temperatura\", \"valor_en_tiempo\"):\n            if not _hay_valor(datos, \"tiempo_objetivo\", \"tiempo\"):\n                return formula_enfriamiento(datos)\n            tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n            temperatura = funcion(tiempo_objetivo)\n            pasos.append(crear_paso(\n                \"Temperatura solicitada\",\n                \"Se evalúa el modelo en el tiempo indicado.\",\n                rf\"\\boxed{{T({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(temperatura)}}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=\"newton_constante\",\n                modelo=\"Ley de enfriamiento de Newton: T'=-k(T-Ta)\",\n                tipo=\"temperatura\",\n                resultado=redondear(temperatura),\n                unidad=\"°C\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"tiempo_objetivo\", \"tiempo\", \"tiempo_para_temperatura\"):\n            if not _hay_valor(datos, \"temperatura_objetivo\", \"T_objetivo\"):\n                return formula_enfriamiento(datos)\n            temperatura_objetivo = validar_numero(obtener_valor(datos, (\"temperatura_objetivo\", \"T_objetivo\"), \"temperatura objetivo\"), \"Temperatura objetivo\")\n            diferencia_inicial = temperatura_inicial - temperatura_ambiente\n            diferencia_objetivo = temperatura_objetivo - temperatura_ambiente\n            if diferencia_inicial * diferencia_objetivo <= 0:\n                raise ErrorValidacion(\"La temperatura objetivo debe estar del mismo lado de la temperatura ambiente que la inicial.\")\n            if abs(diferencia_objetivo) > abs(diferencia_inicial):\n                raise ErrorValidacion(\"La temperatura objetivo debe estar entre la inicial y la ambiente.\")\n            tiempo = -log(diferencia_objetivo / diferencia_inicial) / constante_k\n            pasos.append(crear_paso(\n                \"Tiempo para alcanzar una temperatura\",\n                \"Se despeja t usando logaritmo natural.\",\n                rf\"\\begin{{gathered}}{formatear_numero(temperatura_objetivo)}={ta}+({diferencia})e^{{-{k}t}}\\\\[6px]\"\n                rf\"t=-\\frac{{1}}{{{k}}}\\ln\\left(\\frac{{{formatear_numero(temperatura_objetivo)}-{ta}}}{{{diferencia}}}\\right)\\\\[6px]\"\n                rf\"\\boxed{{t\\approx {formatear_numero(tiempo)}}}\\end{{gathered}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=\"newton_constante\",\n                modelo=\"Ley de enfriamiento de Newton: T'=-k(T-Ta)\",\n                tipo=\"tiempo_objetivo\",\n                resultado=redondear(tiempo),\n                unidad=\"unidades de tiempo\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        if tipo_calculo in (\"equilibrio\", \"limite\"):\n            pasos.append(crear_paso(\n                \"Comportamiento límite\",\n                \"Cuando el tiempo crece, la temperatura del objeto se aproxima a la del ambiente.\",\n                rf\"\\lim_{{t\\to\\infty}}T(t)=\\boxed{{T_a={ta}}}\",\n            ))\n            return crear_respuesta_modelo(\n                modulo=MODULO,\n                variante=\"newton_constante\",\n                modelo=\"Ley de enfriamiento de Newton: T'=-k(T-Ta)\",\n                tipo=\"equilibrio\",\n                resultado=redondear(temperatura_ambiente),\n                unidad=\"°C\",\n                constantes=constantes,\n                pasos=pasos,\n            )\n\n        raise ErrorValidacion(\"Tipo de cálculo inválido para enfriamiento.\")\n    except (ErrorValidacion, ValueError, ZeroDivisionError) as error:\n        return crear_respuesta_error(str(error))",
    "datosBaseMezclas": "def _datos_base(datos: dict[str, Any]) -> tuple[float, float, float, float, float, float | None]:\n    sal_inicial = validar_no_negativo(\n        obtener_valor(datos, (\"sal_inicial\", \"cantidad_inicial\", \"A0\"), \"cantidad inicial de soluto\"),\n        \"Cantidad inicial de soluto\",\n    )\n    volumen_inicial = validar_positivo(\n        obtener_valor(datos, (\"volumen_inicial\", \"V0\"), \"volumen inicial\"),\n        \"Volumen inicial\",\n    )\n    caudal_entrada = validar_no_negativo(\n        obtener_valor(datos, (\"caudal_entrada\", \"r_entrada\", \"rin\"), \"caudal de entrada\"),\n        \"Caudal de entrada\",\n    )\n    caudal_salida = validar_no_negativo(\n        obtener_valor(datos, (\"caudal_salida\", \"r_salida\", \"rout\"), \"caudal de salida\"),\n        \"Caudal de salida\",\n    )\n    concentracion_entrada = validar_no_negativo(\n        obtener_valor(datos, (\"concentracion_entrada\", \"c_entrada\", \"cin\"), \"concentración de entrada\"),\n        \"Concentración de entrada\",\n    )\n    concentracion_salida = _obtener_concentracion_salida(datos)\n    if caudal_entrada == 0 and caudal_salida == 0:\n        raise ErrorValidacion(\"Al menos uno de los caudales debe ser mayor que cero.\")\n    return sal_inicial, volumen_inicial, caudal_entrada, caudal_salida, concentracion_entrada, concentracion_salida",
    "resolverMezclaConstante": "def _resolver_volumen_constante(datos: dict[str, Any]) -> dict[str, Any]:\n    sal_inicial, volumen_inicial, caudal_entrada, caudal_salida, concentracion_entrada, concentracion_salida = _datos_base(datos)\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"cantidad\"))\n\n    if abs(caudal_entrada - caudal_salida) > 1e-9:\n        raise ErrorValidacion(\"Para la variante volumen_constante, el caudal de entrada debe ser igual al caudal de salida.\")\n    if caudal_salida == 0:\n        raise ErrorValidacion(\"En volumen constante debe existir caudal de salida.\")\n    if concentracion_salida is not None:\n        return _resolver_volumen_constante_con_salida_fija(\n            datos,\n            sal_inicial,\n            volumen_inicial,\n            caudal_entrada,\n            caudal_salida,\n            concentracion_entrada,\n            concentracion_salida,\n        )\n\n    constante_salida = caudal_salida / volumen_inicial\n    entrada_soluto = caudal_entrada * concentracion_entrada\n    equilibrio = entrada_soluto / constante_salida\n    coeficiente_inicial = sal_inicial - equilibrio\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = expresion_mezcla_volumen_constante(sal_inicial, equilibrio, constante_salida, variable_t)\n\n    def cantidad(tiempo: float) -> float:\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    a0 = formatear_numero(sal_inicial)\n    v0 = formatear_numero(volumen_inicial)\n    rin = formatear_numero(caudal_entrada)\n    rout = formatear_numero(caudal_salida)\n    cin = formatear_numero(concentracion_entrada)\n    alfa = formatear_numero(constante_salida, DECIMALES_CONSTANTE)\n    entrada = formatear_numero(entrada_soluto)\n    limite = formatear_numero(equilibrio)\n    coef = formatear_numero(coeficiente_inicial)\n\n    pasos = [\n        crear_paso(\n            \"Modelo diferencial\",\n            \"La cantidad de soluto cambia por entrada menos salida. Como los caudales son iguales, el volumen permanece constante.\",\n            r\"\\frac{dA}{dt}=r_e c_e-r_s\\frac{A}{V}\",\n        ),\n        crear_paso(\n            \"Sustitución del modelo\",\n            \"Se reemplazan caudales, concentración y volumen.\",\n            rf\"\\begin{{gathered}}V={v0},\\quad r_e={rin},\\quad r_s={rout},\\quad c_e={cin}\\\\[6px]\"\n            rf\"\\frac{{dA}}{{dt}}={rin}({cin})-{rout}\\frac{{A}}{{{v0}}}\\\\[6px]\"\n            rf\"\\boxed{{\\frac{{dA}}{{dt}}={entrada}-{alfa}A}}\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Solución de la EDO lineal\",\n            \"La solución se aproxima a un equilibrio donde entrada y salida se compensan.\",\n            rf\"\\begin{{gathered}}A(t)=A_\\infty+(A_0-A_\\infty)e^{{-({alfa})t}}\\\\[6px]\"\n            rf\"A_\\infty=\\frac{{r_e c_e}}{{r_s/V}}={limite}\\\\[6px]\"\n            rf\"\\boxed{{A(t)={limite}+({coef})e^{{-{alfa}t}}}}\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Chequeo simbólico con SymPy\",\n            \"La cantidad de soluto se representa de forma simbólica antes de evaluar o calcular el límite.\",\n            paso_sympy(\"A\", variable_t, expresion_sympy),\n        ),\n    ]\n\n    constantes = {\n        \"entrada_soluto\": redondear(entrada_soluto),\n        \"coeficiente_salida\": redondear(constante_salida, DECIMALES_CONSTANTE),\n        \"limite\": redondear(equilibrio),\n        \"volumen\": redondear(volumen_inicial),\n    }\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante\",\n            tipo=\"funcion\",\n            resultado=f\"A(t)={limite}+({coef})e^(-{alfa}t)\",\n            resultado_latex=rf\"A(t)={limite}+({coef})e^{{-{alfa}t}}\",\n            unidad=\"función\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"cantidad\", \"valor_en_tiempo\", \"sal\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo)\n        concentracion = valor / volumen_inicial\n        pasos.append(crear_paso(\n            \"Cantidad solicitada\",\n            \"Se evalúa la función A(t) en el tiempo indicado.\",\n            rf\"\\boxed{{A({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante\",\n            tipo=\"cantidad\",\n            resultado=redondear(valor),\n            unidad=\"kg de soluto\",\n            constantes=constantes,\n            pasos=pasos,\n            metadatos={\"concentracion\": redondear(concentracion)},\n        )\n\n    if tipo_calculo in (\"concentracion\", \"concentracion_en_tiempo\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo) / volumen_inicial\n        pasos.append(crear_paso(\n            \"Concentración solicitada\",\n            \"La concentración es la cantidad de soluto dividida entre el volumen.\",\n            rf\"\\boxed{{C({formatear_numero(tiempo_objetivo)})=\\frac{{A({formatear_numero(tiempo_objetivo)})}}{{{v0}}}\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante\",\n            tipo=\"concentracion\",\n            resultado=redondear(valor),\n            unidad=\"kg/L\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"limite\", \"equilibrio\"):\n        pasos.append(crear_paso(\n            \"Límite del modelo\",\n            \"Cuando t crece, el término exponencial tiende a cero.\",\n            rf\"\\lim_{{t\\to\\infty}}A(t)=\\boxed{{{limite}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante\",\n            tipo=\"limite\",\n            resultado=redondear(equilibrio),\n            unidad=\"kg de soluto\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para mezclas con volumen constante.\")",
    "resolverMezclaConstanteSalidaFija": "def _resolver_volumen_constante_con_salida_fija(\n    datos: dict[str, Any],\n    sal_inicial: float,\n    volumen_inicial: float,\n    caudal_entrada: float,\n    caudal_salida: float,\n    concentracion_entrada: float,\n    concentracion_salida: float,\n) -> dict[str, Any]:\n    \"\"\"Resuelve dA/dt = r_e c_e - r_s c_s cuando c_s se ingresa explícitamente.\"\"\"\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"cantidad\"))\n    entrada_soluto = caudal_entrada * concentracion_entrada\n    salida_soluto = caudal_salida * concentracion_salida\n    pendiente = entrada_soluto - salida_soluto\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = sal_inicial + pendiente * variable_t\n\n    def cantidad(tiempo: float) -> float:\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    a0 = formatear_numero(sal_inicial)\n    v0 = formatear_numero(volumen_inicial)\n    rin = formatear_numero(caudal_entrada)\n    rout = formatear_numero(caudal_salida)\n    cin = formatear_numero(concentracion_entrada)\n    cs = formatear_numero(concentracion_salida)\n    entrada = formatear_numero(entrada_soluto)\n    salida = formatear_numero(salida_soluto)\n    m = formatear_numero(pendiente)\n\n    pasos = [\n        crear_paso(\n            \"Modelo diferencial con salida fija\",\n            \"Como se ingresó concentración de salida, la salida de soluto se evalúa como r_s c_s. Si no se ingresa, el modelo clásico usa A/V.\",\n            r\"\\frac{dA}{dt}=r_ec_e-r_sc_s\",\n        ),\n        crear_paso(\n            \"Sustitución de datos\",\n            \"Se reemplazan concentración de entrada, concentración de salida y caudales.\",\n            rf\"\\begin{{gathered}}\"\n            rf\"V={v0},\\quad r_e={rin},\\quad c_e={cin},\\quad r_s={rout},\\quad c_s={cs}\\\\[6px]\"\n            rf\"\\frac{{dA}}{{dt}}={rin}({cin})-{rout}({cs})={entrada}-{salida}\\\\[6px]\"\n            rf\"\\boxed{{\\frac{{dA}}{{dt}}={m}}}\"\n            rf\"\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Integración directa\",\n            \"Con entrada y salida fijas, la cantidad cambia linealmente respecto al tiempo.\",\n            rf\"\\begin{{gathered}}A(t)=A_0+({m})t\\\\[6px]\\boxed{{A(t)={a0}+({m})t}}\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Chequeo simbólico con SymPy\",\n            \"La expresión lineal se conserva como fórmula matemática antes de evaluar.\",\n            paso_sympy(\"A\", variable_t, expresion_sympy),\n        ),\n    ]\n\n    constantes = {\n        \"entrada_soluto\": redondear(entrada_soluto),\n        \"salida_soluto\": redondear(salida_soluto),\n        \"pendiente\": redondear(pendiente),\n        \"volumen\": redondear(volumen_inicial),\n        \"concentracion_salida\": redondear(concentracion_salida),\n    }\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante y concentración de salida fija\",\n            tipo=\"funcion\",\n            resultado=f\"A(t)={a0}+({m})t\",\n            resultado_latex=rf\"A(t)={a0}+({m})t\",\n            unidad=\"función\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"cantidad\", \"valor_en_tiempo\", \"sal\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo)\n        concentracion = valor / volumen_inicial\n        tx = formatear_numero(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Cantidad solicitada\",\n            \"Se evalúa la función lineal en el tiempo indicado.\",\n            rf\"\\boxed{{A({tx})={a0}+({m})({tx})\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante y concentración de salida fija\",\n            tipo=\"cantidad\",\n            resultado=redondear(valor),\n            unidad=\"kg de soluto\",\n            constantes=constantes,\n            pasos=pasos,\n            metadatos={\"concentracion\": redondear(concentracion)},\n        )\n\n    if tipo_calculo in (\"concentracion\", \"concentracion_en_tiempo\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo) / volumen_inicial\n        tx = formatear_numero(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Concentración solicitada\",\n            \"Como el volumen es constante, la concentración se obtiene dividiendo A(t) entre V.\",\n            rf\"\\boxed{{C({tx})=\\frac{{A({tx})}}{{{v0}}}\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante y concentración de salida fija\",\n            tipo=\"concentracion\",\n            resultado=redondear(valor),\n            unidad=\"kg/L\",\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    if tipo_calculo in (\"limite\", \"equilibrio\"):\n        if abs(pendiente) < 1e-12:\n            resultado = sal_inicial\n            resultado_latex = rf\"\\lim_{{t\\to\\infty}}A(t)={a0}\"\n            unidad = \"kg de soluto\"\n        elif pendiente > 0:\n            resultado = \"La cantidad crece linealmente sin límite finito.\"\n            resultado_latex = r\"\\lim_{t\\to\\infty}A(t)=+\\infty\"\n            unidad = \"comportamiento\"\n        else:\n            resultado = \"El modelo lineal tiende a valores negativos; físicamente debe detenerse cuando A(t)=0.\"\n            resultado_latex = r\"A(t)=0\\quad\\Rightarrow\\quad t=\\frac{A_0}{r_sc_s-r_ec_e}\"\n            unidad = \"comportamiento\"\n        pasos.append(crear_paso(\n            \"Comportamiento límite\",\n            \"Con concentración de salida fija no aparece equilibrio exponencial; el comportamiento depende de la pendiente neta.\",\n            resultado_latex,\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_constante\",\n            modelo=\"Mezclas con volumen constante y concentración de salida fija\",\n            tipo=\"limite\",\n            resultado=redondear(resultado) if isinstance(resultado, (int, float)) else resultado,\n            resultado_latex=resultado_latex,\n            unidad=unidad,\n            constantes=constantes,\n            pasos=pasos,\n        )\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para mezclas con volumen constante.\")",
    "resolverMezclaVariable": "def _resolver_volumen_variable(datos: dict[str, Any]) -> dict[str, Any]:\n    sal_inicial, volumen_inicial, caudal_entrada, caudal_salida, concentracion_entrada, concentracion_salida = _datos_base(datos)\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"cantidad\"))\n    delta_volumen = caudal_entrada - caudal_salida\n    if abs(delta_volumen) < 1e-9:\n        return _resolver_volumen_constante({**datos, \"variante\": \"volumen_constante\"})\n    if caudal_entrada <= 0:\n        raise ErrorValidacion(\"La variante de volumen variable requiere caudal de entrada positivo.\")\n    if concentracion_salida is not None:\n        return _resolver_volumen_variable_con_salida_fija(\n            datos,\n            sal_inicial,\n            volumen_inicial,\n            caudal_entrada,\n            caudal_salida,\n            concentracion_entrada,\n            concentracion_salida,\n        )\n\n    exponente = caudal_salida / delta_volumen\n    coeficiente_inicial = sal_inicial - concentracion_entrada * volumen_inicial\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = expresion_mezcla_volumen_variable(\n        sal_inicial,\n        volumen_inicial,\n        concentracion_entrada,\n        delta_volumen,\n        exponente,\n        variable_t,\n    )\n\n    def volumen(tiempo: float) -> float:\n        return volumen_inicial + delta_volumen * tiempo\n\n    def cantidad(tiempo: float) -> float:\n        volumen_actual = volumen(tiempo)\n        if volumen_actual <= 0:\n            raise ErrorValidacion(\"El tanque queda vacío antes o justo en el tiempo solicitado.\")\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    a0 = formatear_numero(sal_inicial)\n    v0 = formatear_numero(volumen_inicial)\n    rin = formatear_numero(caudal_entrada)\n    rout = formatear_numero(caudal_salida)\n    cin = formatear_numero(concentracion_entrada)\n    delta = formatear_numero(delta_volumen)\n    m = formatear_numero(exponente, DECIMALES_CONSTANTE)\n    coef = formatear_numero(coeficiente_inicial)\n\n    tiempo_vaciado = None\n    advertencias: list[str] = []\n    if delta_volumen < 0:\n        tiempo_vaciado = volumen_inicial / (caudal_salida - caudal_entrada)\n        advertencias.append(f\"El tanque se vacía en t={formatear_numero(tiempo_vaciado)} si no se detiene el proceso.\")\n\n    pasos = [\n        crear_paso(\n            \"Modelo diferencial\",\n            \"Como los caudales no son iguales, el volumen cambia con el tiempo.\",\n            r\"\\frac{dA}{dt}=r_e c_e-r_s\\frac{A}{V(t)},\\qquad V(t)=V_0+(r_e-r_s)t\",\n        ),\n        crear_paso(\n            \"Sustitución del volumen variable\",\n            \"Se reemplazan los datos de entrada del tanque.\",\n            rf\"\\begin{{gathered}}V(t)={v0}+({delta})t\\\\[6px]\"\n            rf\"\\frac{{dA}}{{dt}}={rin}({cin})-{rout}\\frac{{A}}{{{v0}+({delta})t}}\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Solución del modelo lineal\",\n            \"Usando el factor integrante del volumen variable, se obtiene una expresión cerrada para A(t).\",\n            rf\"\\boxed{{A(t)={cin}V(t)+({a0}-{cin}\\cdot {v0})\\left(\\frac{{{v0}}}{{V(t)}}\\right)^{{{m}}}}}\",\n        ),\n        crear_paso(\n            \"Chequeo simbólico con SymPy\",\n            \"SymPy mantiene la expresión con V(t) variable antes de evaluar la cantidad o concentración.\",\n            paso_sympy(\"A\", variable_t, expresion_sympy),\n        ),\n    ]\n\n    constantes = {\n        \"delta_volumen\": redondear(delta_volumen),\n        \"exponente\": redondear(exponente, DECIMALES_CONSTANTE),\n        \"coeficiente_inicial\": redondear(coeficiente_inicial),\n    }\n    if tiempo_vaciado is not None and isfinite(tiempo_vaciado):\n        constantes[\"tiempo_vaciado\"] = redondear(tiempo_vaciado)\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable\",\n            tipo=\"funcion\",\n            resultado=f\"A(t)={cin}V(t)+({coef})({v0}/V(t))^{m}, V(t)={v0}+({delta})t\",\n            resultado_latex=rf\"A(t)={cin}V(t)+({coef})\\left(\\frac{{{v0}}}{{V(t)}}\\right)^{{{m}}},\\quad V(t)={v0}+({delta})t\",\n            unidad=\"función\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    if tipo_calculo in (\"cantidad\", \"valor_en_tiempo\", \"sal\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo)\n        volumen_actual = volumen(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Cantidad solicitada\",\n            \"Se evalúa la solución con el volumen correspondiente al tiempo indicado.\",\n            rf\"\\begin{{gathered}}V({formatear_numero(tiempo_objetivo)})={formatear_numero(volumen_actual)}\\\\[6px]\"\n            rf\"\\boxed{{A({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\\end{{gathered}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable\",\n            tipo=\"cantidad\",\n            resultado=redondear(valor),\n            unidad=\"kg de soluto\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n            metadatos={\"volumen_actual\": redondear(volumen_actual), \"concentracion\": redondear(valor / volumen_actual)},\n        )\n\n    if tipo_calculo in (\"concentracion\", \"concentracion_en_tiempo\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        volumen_actual = volumen(tiempo_objetivo)\n        valor = cantidad(tiempo_objetivo) / volumen_actual\n        pasos.append(crear_paso(\n            \"Concentración solicitada\",\n            \"Se calcula C(t)=A(t)/V(t).\",\n            rf\"\\boxed{{C({formatear_numero(tiempo_objetivo)})\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable\",\n            tipo=\"concentracion\",\n            resultado=redondear(valor),\n            unidad=\"kg/L\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    if tipo_calculo in (\"limite\", \"equilibrio\"):\n        if delta_volumen > 0:\n            resultado = f\"La concentración tiende a {formatear_numero(concentracion_entrada)} kg/L y la cantidad crece sin cota porque el volumen aumenta.\"\n            resultado_latex = rf\"\\lim_{{t\\to\\infty}}C(t)={formatear_numero(concentracion_entrada)}\"\n        else:\n            resultado = \"No existe límite infinito físico: el tanque se vacía en tiempo finito.\"\n            resultado_latex = r\"V(t)=0\\quad\\text{en tiempo finito}\"\n        pasos.append(crear_paso(\n            \"Comportamiento límite\",\n            \"En volumen variable el límite depende de si el tanque se llena o se vacía.\",\n            rf\"V(t)={v0}+({delta})t\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable\",\n            tipo=\"limite\",\n            resultado=resultado,\n            resultado_latex=resultado_latex,\n            unidad=\"comportamiento\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para mezclas con volumen variable.\")",
    "resolverMezclaVariableSalidaFija": "def _resolver_volumen_variable_con_salida_fija(\n    datos: dict[str, Any],\n    sal_inicial: float,\n    volumen_inicial: float,\n    caudal_entrada: float,\n    caudal_salida: float,\n    concentracion_entrada: float,\n    concentracion_salida: float,\n) -> dict[str, Any]:\n    \"\"\"Resuelve volumen variable con salida de concentración fija.\"\"\"\n    tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"cantidad\"))\n    delta_volumen = caudal_entrada - caudal_salida\n    entrada_soluto = caudal_entrada * concentracion_entrada\n    salida_soluto = caudal_salida * concentracion_salida\n    pendiente = entrada_soluto - salida_soluto\n    variable_t = crear_variable(\"t\")\n    expresion_sympy = sal_inicial + pendiente * variable_t\n\n    def volumen(tiempo: float) -> float:\n        return volumen_inicial + delta_volumen * tiempo\n\n    def cantidad(tiempo: float) -> float:\n        volumen_actual = volumen(tiempo)\n        if volumen_actual <= 0:\n            raise ErrorValidacion(\"El tanque queda vacío antes o justo en el tiempo solicitado.\")\n        return evaluar(expresion_sympy, variable_t, tiempo)\n\n    a0 = formatear_numero(sal_inicial)\n    v0 = formatear_numero(volumen_inicial)\n    rin = formatear_numero(caudal_entrada)\n    rout = formatear_numero(caudal_salida)\n    cin = formatear_numero(concentracion_entrada)\n    cs = formatear_numero(concentracion_salida)\n    delta = formatear_numero(delta_volumen)\n    m = formatear_numero(pendiente)\n\n    tiempo_vaciado = None\n    advertencias: list[str] = []\n    if delta_volumen < 0:\n        tiempo_vaciado = volumen_inicial / (caudal_salida - caudal_entrada)\n        advertencias.append(f\"El tanque se vacía en t={formatear_numero(tiempo_vaciado)} si no se detiene el proceso.\")\n\n    pasos = [\n        crear_paso(\n            \"Modelo diferencial con volumen variable y salida fija\",\n            \"El volumen cambia con el tiempo y la salida de soluto se calcula con la concentración de salida ingresada.\",\n            r\"\\frac{dA}{dt}=r_ec_e-r_sc_s,\\qquad V(t)=V_0+(r_e-r_s)t\",\n        ),\n        crear_paso(\n            \"Sustitución de datos\",\n            \"Se reemplazan caudales, concentraciones y volumen inicial.\",\n            rf\"\\begin{{gathered}}V(t)={v0}+({delta})t\\\\[6px]\"\n            rf\"\\frac{{dA}}{{dt}}={rin}({cin})-{rout}({cs})\\\\[6px]\"\n            rf\"\\boxed{{A(t)={a0}+({m})t}}\\end{{gathered}}\",\n        ),\n        crear_paso(\n            \"Concentración dentro del tanque\",\n            \"Para concentración se divide la cantidad calculada entre el volumen actual.\",\n            rf\"\\boxed{{C(t)=\\frac{{A(t)}}{{V(t)}}=\\frac{{{a0}+({m})t}}{{{v0}+({delta})t}}}}\",\n        ),\n        crear_paso(\n            \"Chequeo simbólico con SymPy\",\n            \"SymPy conserva la expresión de cantidad antes de evaluar o dividir por el volumen.\",\n            paso_sympy(\"A\", variable_t, expresion_sympy),\n        ),\n    ]\n\n    constantes = {\n        \"delta_volumen\": redondear(delta_volumen),\n        \"entrada_soluto\": redondear(entrada_soluto),\n        \"salida_soluto\": redondear(salida_soluto),\n        \"pendiente\": redondear(pendiente),\n        \"concentracion_salida\": redondear(concentracion_salida),\n    }\n    if tiempo_vaciado is not None and isfinite(tiempo_vaciado):\n        constantes[\"tiempo_vaciado\"] = redondear(tiempo_vaciado)\n\n    if tipo_calculo in (\"funcion\", \"solucion\", \"solucion_particular\"):\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable y concentración de salida fija\",\n            tipo=\"funcion\",\n            resultado=f\"A(t)={a0}+({m})t, V(t)={v0}+({delta})t\",\n            resultado_latex=rf\"A(t)={a0}+({m})t,\\qquad V(t)={v0}+({delta})t\",\n            unidad=\"función\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    if tipo_calculo in (\"cantidad\", \"valor_en_tiempo\", \"sal\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor = cantidad(tiempo_objetivo)\n        volumen_actual = volumen(tiempo_objetivo)\n        tx = formatear_numero(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Cantidad solicitada\",\n            \"Se evalúa A(t) y se verifica el volumen actual del tanque.\",\n            rf\"\\begin{{gathered}}V({tx})={formatear_numero(volumen_actual)}\\\\[6px]\\boxed{{A({tx})\\approx {formatear_numero(valor)}}}\\end{{gathered}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable y concentración de salida fija\",\n            tipo=\"cantidad\",\n            resultado=redondear(valor),\n            unidad=\"kg de soluto\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n            metadatos={\"volumen_actual\": redondear(volumen_actual), \"concentracion\": redondear(valor / volumen_actual)},\n        )\n\n    if tipo_calculo in (\"concentracion\", \"concentracion_en_tiempo\"):\n        tiempo_objetivo = validar_no_negativo(obtener_valor(datos, (\"tiempo_objetivo\", \"tiempo\"), \"tiempo objetivo\"), \"Tiempo objetivo\")\n        valor_cantidad = cantidad(tiempo_objetivo)\n        volumen_actual = volumen(tiempo_objetivo)\n        valor = valor_cantidad / volumen_actual\n        tx = formatear_numero(tiempo_objetivo)\n        pasos.append(crear_paso(\n            \"Concentración solicitada\",\n            \"Se divide la cantidad de soluto entre el volumen actual.\",\n            rf\"\\boxed{{C({tx})=\\frac{{A({tx})}}{{V({tx})}}\\approx {formatear_numero(valor)}}}\",\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable y concentración de salida fija\",\n            tipo=\"concentracion\",\n            resultado=redondear(valor),\n            unidad=\"kg/L\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    if tipo_calculo in (\"limite\", \"equilibrio\"):\n        if delta_volumen > 0:\n            limite_concentracion = pendiente / delta_volumen\n            resultado = f\"La concentración tiende a {formatear_numero(limite_concentracion)} kg/L si el proceso continúa sin restricciones físicas.\"\n            resultado_latex = rf\"\\lim_{{t\\to\\infty}}C(t)=\\frac{{r_ec_e-r_sc_s}}{{r_e-r_s}}={formatear_numero(limite_concentracion)}\"\n        else:\n            resultado = \"No existe límite infinito físico: el tanque se vacía en tiempo finito.\"\n            resultado_latex = r\"V(t)=0\\quad\\text{en tiempo finito}\"\n        pasos.append(crear_paso(\n            \"Comportamiento límite\",\n            \"El límite se analiza con la relación entre la pendiente de soluto y la pendiente de volumen.\",\n            resultado_latex,\n        ))\n        return crear_respuesta_modelo(\n            modulo=MODULO,\n            variante=\"volumen_variable\",\n            modelo=\"Mezclas con volumen variable y concentración de salida fija\",\n            tipo=\"limite\",\n            resultado=resultado,\n            resultado_latex=resultado_latex,\n            unidad=\"comportamiento\",\n            constantes=constantes,\n            pasos=pasos,\n            advertencias=advertencias,\n        )\n\n    raise ErrorValidacion(\"Tipo de cálculo inválido para mezclas con volumen variable.\")",
    "resolverMezclas": "def resolver_mezclas(datos: dict[str, Any]) -> dict[str, Any]:\n    \"\"\"Método único del módulo mezclas que evalúa sus variantes internas.\"\"\"\n    try:\n        variante = normalizar_texto(datos.get(\"variante\", \"volumen_constante\"))\n        tipo_calculo = normalizar_texto(datos.get(\"tipo_calculo\", \"cantidad\"))\n        if tipo_calculo in (\"formula_simbolica\", \"formula_general\", \"planteamiento\"):\n            return formula_mezclas({**datos, \"variante\": variante})\n        if variante in (\"volumen_constante\", \"tanque_constante\", \"mezcla_constante\"):\n            return _resolver_volumen_constante(datos)\n        if variante in (\"volumen_variable\", \"tanque_variable\", \"mezcla_variable\"):\n            return _resolver_volumen_variable(datos)\n        raise ErrorValidacion(f\"Variante no soportada en mezclas: {variante}.\")\n    except (ErrorValidacion, ValueError, ZeroDivisionError) as error:\n        return crear_respuesta_error(str(error))",
    "derivacionesCompleto": "\"\"\"Derivaciones matemáticas base para enriquecer las respuestas del backend.\n\nEstas secciones se agregan antes de los pasos numéricos de cada modelo para que\nla aplicación muestre de dónde sale la fórmula general usada por cada variante.\nSe mantienen como texto/LaTeX estático porque la lógica dinámica y segura de\ncálculo sigue viviendo en los módulos de modelos y en ``utils.simbolico``.\n\"\"\"\nfrom __future__ import annotations\n\nfrom copy import deepcopy\n\nPaso = dict[str, str]\n\n\nDERIVACIONES: dict[tuple[str, str], list[Paso]] = {\n    (\"crecimiento\", \"crecimiento_proporcional\"): [\n        {\n            \"titulo\": \"Modelo diferencial proporcional\",\n            \"descripcion\": \"La hipótesis dice que la rapidez de cambio es proporcional a la cantidad presente. Por eso se plantea una EDO separable de primer orden.\",\n            \"latex\": r\"\\frac{dP}{dt}=kP\",\n        },\n        {\n            \"titulo\": \"Separación e integración\",\n            \"descripcion\": \"Se separan las variables para integrar población en un lado y tiempo en el otro.\",\n            \"latex\": r\"\\frac{1}{P}\\,dP=k\\,dt\\;\\Longrightarrow\\;\\int\\frac{1}{P}\\,dP=\\int k\\,dt\\;\\Longrightarrow\\;\\ln|P|=kt+C\",\n        },\n        {\n            \"titulo\": \"Despeje de la solución general\",\n            \"descripcion\": \"Al aplicar exponencial, la constante aditiva se transforma en una constante multiplicativa positiva.\",\n            \"latex\": r\"P(t)=Ce^{kt}\",\n        },\n        {\n            \"titulo\": \"Condición inicial y constante C\",\n            \"descripcion\": \"La condición inicial determina la constante de integración.\",\n            \"latex\": r\"P(0)=P_0\\;\\Longrightarrow\\;C=P_0\\;\\Longrightarrow\\;P(t)=P_0e^{kt}\",\n        },\n        {\n            \"titulo\": \"Inferencia de k cuando existe un dato conocido\",\n            \"descripcion\": \"Si se conoce una medición posterior, el sistema despeja k sin obligar al usuario a escribirla manualmente.\",\n            \"latex\": r\"P(t_1)=P_1\\;\\Longrightarrow\\;P_1=P_0e^{kt_1}\\;\\Longrightarrow\\;k=\\frac{1}{t_1}\\ln\\left(\\frac{P_1}{P_0}\\right)\",\n        },\n    ],\n    (\"crecimiento\", \"interes_continuo\"): [\n        {\n            \"titulo\": \"Modelo de capital con capitalización continua\",\n            \"descripcion\": \"El capital crece proporcionalmente al capital disponible. La tasa porcentual se transforma a tasa decimal antes de construir la expresión.\",\n            \"latex\": r\"\\frac{dS}{dt}=rS\",\n        },\n        {\n            \"titulo\": \"Separación de variables\",\n            \"descripcion\": \"El procedimiento es análogo al crecimiento poblacional, reemplazando la población por el capital.\",\n            \"latex\": r\"\\frac{1}{S}\\,dS=r\\,dt\\;\\Longrightarrow\\;\\ln|S|=rt+C\",\n        },\n        {\n            \"titulo\": \"Fórmula general y condición inicial\",\n            \"descripcion\": \"La condición S(0)=S0 convierte la constante de integración en el capital inicial.\",\n            \"latex\": r\"S(t)=Ce^{rt},\\quad S(0)=S_0\\Rightarrow C=S_0\\Rightarrow S(t)=S_0e^{rt}\",\n        },\n        {\n            \"titulo\": \"Uso de la tasa porcentual\",\n            \"descripcion\": \"Cuando el usuario ingresa una tasa en porcentaje, el backend la transforma a decimal para evitar confusiones entre 6 y 0.06.\",\n            \"latex\": r\"r=\\frac{\\text{tasa porcentual}}{100}\",\n        },\n    ],\n    (\"crecimiento\", \"entrada_constante\"): [\n        {\n            \"titulo\": \"Modelo lineal con fuente externa\",\n            \"descripcion\": \"La población no solo crece proporcionalmente; además recibe una entrada constante b por unidad de tiempo.\",\n            \"latex\": r\"\\frac{dP}{dt}=kP+b\\;\\Longleftrightarrow\\;\\frac{dP}{dt}-kP=b\",\n        },\n        {\n            \"titulo\": \"Factor integrante\",\n            \"descripcion\": \"La ecuación lineal se resuelve multiplicando por el factor integrante asociado a -k.\",\n            \"latex\": r\"\\mu(t)=e^{\\int -k\\,dt}=e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Integración del producto\",\n            \"descripcion\": \"Al multiplicar por el factor integrante, el lado izquierdo se convierte en una derivada exacta.\",\n            \"latex\": r\"e^{-kt}\\frac{dP}{dt}-ke^{-kt}P=be^{-kt}\\;\\Longrightarrow\\;\\frac{d}{dt}\\left(Pe^{-kt}\\right)=be^{-kt}\",\n        },\n        {\n            \"titulo\": \"Solución general\",\n            \"descripcion\": \"Después de integrar y despejar P(t), aparece una parte exponencial y un término de equilibrio desplazado.\",\n            \"latex\": r\"Pe^{-kt}=\\int be^{-kt}dt=-\\frac{b}{k}e^{-kt}+C\\;\\Longrightarrow\\;P(t)=Ce^{kt}-\\frac{b}{k}\",\n        },\n        {\n            \"titulo\": \"Condición inicial y constante C\",\n            \"descripcion\": \"La condición inicial permite reemplazar C por una expresión en términos de P0, b y k.\",\n            \"latex\": r\"P(0)=P_0\\Rightarrow P_0=C-\\frac{b}{k}\\Rightarrow C=P_0+\\frac{b}{k}\\Rightarrow P(t)=\\left(P_0+\\frac{b}{k}\\right)e^{kt}-\\frac{b}{k}\",\n        },\n    ],\n    (\"crecimiento\", \"caida_resistencia\"): [\n        {\n            \"titulo\": \"Modelo físico de caída con resistencia lineal\",\n            \"descripcion\": \"La gravedad aumenta la velocidad y la resistencia proporcional a la velocidad la reduce.\",\n            \"latex\": r\"\\frac{dv}{dt}=g-kv\\;\\Longleftrightarrow\\;\\frac{dv}{dt}+kv=g\",\n        },\n        {\n            \"titulo\": \"Factor integrante\",\n            \"descripcion\": \"La ecuación es lineal de primer orden y se resuelve con factor integrante.\",\n            \"latex\": r\"\\mu(t)=e^{\\int k\\,dt}=e^{kt}\",\n        },\n        {\n            \"titulo\": \"Integración\",\n            \"descripcion\": \"Al multiplicar por e^{kt}, el lado izquierdo queda como derivada de ve^{kt}.\",\n            \"latex\": r\"\\frac{d}{dt}\\left(ve^{kt}\\right)=ge^{kt}\\;\\Longrightarrow\\;ve^{kt}=\\frac{g}{k}e^{kt}+C\",\n        },\n        {\n            \"titulo\": \"Solución general y condición inicial\",\n            \"descripcion\": \"Al despejar y aplicar v(0)=v0 se obtiene la fórmula particular usada por el sistema.\",\n            \"latex\": r\"v(t)=\\frac{g}{k}+Ce^{-kt},\\quad v(0)=v_0\\Rightarrow C=v_0-\\frac{g}{k}\\Rightarrow v(t)=\\frac{g}{k}+\\left(v_0-\\frac{g}{k}\\right)e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Comprobación de velocidad límite\",\n            \"descripcion\": \"Cuando t crece, el término exponencial desaparece y queda la velocidad terminal.\",\n            \"latex\": r\"\\lim_{t\\to\\infty}v(t)=\\frac{g}{k}\",\n        },\n    ],\n    (\"decaimiento\", \"decaimiento_radiactivo\"): [\n        {\n            \"titulo\": \"Modelo de pérdida proporcional\",\n            \"descripcion\": \"La cantidad disminuye proporcionalmente a la cantidad presente; por eso el signo es negativo.\",\n            \"latex\": r\"\\frac{dA}{dt}=-kA,\\quad k>0\",\n        },\n        {\n            \"titulo\": \"Separación e integración\",\n            \"descripcion\": \"Se separan variables y se integra para construir la función exponencial decreciente.\",\n            \"latex\": r\"\\frac{1}{A}\\,dA=-k\\,dt\\Rightarrow \\ln|A|=-kt+C\",\n        },\n        {\n            \"titulo\": \"Fórmula general y condición inicial\",\n            \"descripcion\": \"La condición inicial A(0)=A0 determina la constante C multiplicativa.\",\n            \"latex\": r\"A(t)=Ce^{-kt},\\quad A(0)=A_0\\Rightarrow C=A_0\\Rightarrow A(t)=A_0e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Inferencia de k y vida media\",\n            \"descripcion\": \"Con una medición posterior se despeja k; con k se calcula el tiempo para llegar a la mitad.\",\n            \"latex\": r\"k=\\frac{1}{t_1}\\ln\\left(\\frac{A_0}{A_1}\\right),\\qquad t_{1/2}=\\frac{\\ln 2}{k}\",\n        },\n    ],\n    (\"decaimiento\", \"absorcion_medicamento\"): [\n        {\n            \"titulo\": \"Modelo de eliminación del medicamento\",\n            \"descripcion\": \"La concentración baja a una tasa proporcional a la concentración actual.\",\n            \"latex\": r\"\\frac{dC}{dt}=-kC\",\n        },\n        {\n            \"titulo\": \"Integración separable\",\n            \"descripcion\": \"El método es separable y produce una función exponencial decreciente.\",\n            \"latex\": r\"\\int\\frac{1}{C}\\,dC=\\int -k\\,dt\\Rightarrow \\ln|C|=-kt+C_1\",\n        },\n        {\n            \"titulo\": \"Función de concentración\",\n            \"descripcion\": \"La condición C(0)=C0 fija la constante de integración.\",\n            \"latex\": r\"C(t)=C_0e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Tiempo para una concentración objetivo\",\n            \"descripcion\": \"Para saber cuándo se alcanza un valor objetivo, se despeja el tiempo con logaritmo natural.\",\n            \"latex\": r\"C_f=C_0e^{-kt}\\Rightarrow t=\\frac{1}{k}\\ln\\left(\\frac{C_0}{C_f}\\right)\",\n        },\n    ],\n    (\"decaimiento\", \"descarga_capacitor\"): [\n        {\n            \"titulo\": \"Modelo eléctrico RC\",\n            \"descripcion\": \"La carga del capacitor disminuye proporcionalmente a la carga presente. En circuitos RC, la constante de decaimiento es 1/(RC).\",\n            \"latex\": r\"\\frac{dq}{dt}=-\\frac{1}{RC}q\",\n        },\n        {\n            \"titulo\": \"Separación de variables\",\n            \"descripcion\": \"La ecuación se resuelve como un decaimiento exponencial, pero manteniendo R y C si no son conocidos.\",\n            \"latex\": r\"\\frac{1}{q}\\,dq=-\\frac{1}{RC}\\,dt\\Rightarrow \\ln|q|=-\\frac{t}{RC}+C_1\",\n        },\n        {\n            \"titulo\": \"Solución general\",\n            \"descripcion\": \"Al aplicar exponencial se obtiene la forma general de descarga.\",\n            \"latex\": r\"q(t)=Ce^{-t/(RC)}\",\n        },\n        {\n            \"titulo\": \"Condición inicial\",\n            \"descripcion\": \"La carga inicial q(0)=q0 determina la constante C.\",\n            \"latex\": r\"q(0)=q_0\\Rightarrow C=q_0\\Rightarrow q(t)=q_0e^{-t/(RC)}\",\n        },\n        {\n            \"titulo\": \"Tiempo para una carga objetivo\",\n            \"descripcion\": \"Si se busca cuándo queda una carga qf, se despeja t con logaritmos.\",\n            \"latex\": r\"q_f=q_0e^{-t/(RC)}\\Rightarrow t=RC\\ln\\left(\\frac{q_0}{q_f}\\right)\",\n        },\n    ],\n    (\"decaimiento\", \"intensidad_luz\"): [\n        {\n            \"titulo\": \"Modelo de atenuación de luz\",\n            \"descripcion\": \"La intensidad disminuye proporcionalmente a la intensidad que queda al avanzar una distancia x.\",\n            \"latex\": r\"\\frac{dI}{dx}=-kI\",\n        },\n        {\n            \"titulo\": \"Integración con distancia\",\n            \"descripcion\": \"Se usa x como variable independiente, pero el procedimiento es el mismo del decaimiento exponencial.\",\n            \"latex\": r\"\\frac{1}{I}\\,dI=-k\\,dx\\Rightarrow \\ln|I|=-kx+C\",\n        },\n        {\n            \"titulo\": \"Función de intensidad\",\n            \"descripcion\": \"La intensidad inicial determina la constante multiplicativa.\",\n            \"latex\": r\"I(x)=I_0e^{-kx}\",\n        },\n        {\n            \"titulo\": \"Inferencia de k desde un porcentaje\",\n            \"descripcion\": \"Si a una distancia x1 queda cierto porcentaje de la intensidad, k se obtiene de la razón I1/I0.\",\n            \"latex\": r\"I_1=I_0e^{-kx_1}\\Rightarrow k=\\frac{1}{x_1}\\ln\\left(\\frac{I_0}{I_1}\\right)\",\n        },\n    ],\n    (\"enfriamiento\", \"newton_constante\"): [\n        {\n            \"titulo\": \"Ley de enfriamiento de Newton\",\n            \"descripcion\": \"La temperatura cambia proporcionalmente a la diferencia entre la temperatura del objeto y la temperatura ambiente.\",\n            \"latex\": r\"\\frac{dT}{dt}=-k(T-T_a)\",\n        },\n        {\n            \"titulo\": \"Cambio de variable\",\n            \"descripcion\": \"Se define u=T-Ta para convertir el modelo en una ecuación separable de decaimiento.\",\n            \"latex\": r\"u=T-T_a\\Rightarrow \\frac{du}{dt}=\\frac{dT}{dt}=-ku\",\n        },\n        {\n            \"titulo\": \"Solución para la diferencia térmica\",\n            \"descripcion\": \"La diferencia con el ambiente disminuye exponencialmente.\",\n            \"latex\": r\"u(t)=Ce^{-kt}\",\n        },\n        {\n            \"titulo\": \"Regreso a temperatura y condición inicial\",\n            \"descripcion\": \"Al volver a T y aplicar T(0)=T0 se obtiene la fórmula general de Newton.\",\n            \"latex\": r\"T(t)-T_a=Ce^{-kt},\\quad T(0)=T_0\\Rightarrow C=T_0-T_a\\Rightarrow T(t)=T_a+(T_0-T_a)e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Inferencia de k\",\n            \"descripcion\": \"Si se conoce una temperatura posterior, la constante se despeja con una razón de diferencias térmicas.\",\n            \"latex\": r\"T_1=T_a+(T_0-T_a)e^{-kt_1}\\Rightarrow k=-\\frac{1}{t_1}\\ln\\left(\\frac{T_1-T_a}{T_0-T_a}\\right)\",\n        },\n    ],\n    (\"enfriamiento\", \"calentamiento_newton\"): [\n        {\n            \"titulo\": \"Modelo de acercamiento al ambiente\",\n            \"descripcion\": \"El mismo modelo sirve para calentamiento cuando el ambiente está por encima del objeto: la diferencia térmica tiende a cero.\",\n            \"latex\": r\"\\frac{dT}{dt}=-k(T-T_a)\",\n        },\n        {\n            \"titulo\": \"Diferencia térmica como variable\",\n            \"descripcion\": \"La variable u=T-Ta puede ser negativa al inicio, pero su magnitud disminuye exponencialmente.\",\n            \"latex\": r\"u=T-T_a\\Rightarrow u'= -ku\\Rightarrow u(t)=Ce^{-kt}\",\n        },\n        {\n            \"titulo\": \"Fórmula general\",\n            \"descripcion\": \"La condición inicial produce la misma fórmula estructural usada en enfriamiento.\",\n            \"latex\": r\"T(t)=T_a+(T_0-T_a)e^{-kt}\",\n        },\n        {\n            \"titulo\": \"Equilibrio térmico\",\n            \"descripcion\": \"A largo plazo el exponencial desaparece y la temperatura se acerca a la del ambiente.\",\n            \"latex\": r\"\\lim_{t\\to\\infty}T(t)=T_a\",\n        },\n    ],\n    (\"mezclas\", \"volumen_constante\"): [\n        {\n            \"titulo\": \"Balance de soluto\",\n            \"descripcion\": \"La cantidad de sal cambia por la sal que entra menos la sal que sale.\",\n            \"latex\": r\"\\frac{dA}{dt}=\\text{entrada}-\\text{salida}\",\n        },\n        {\n            \"titulo\": \"Entrada de soluto\",\n            \"descripcion\": \"La entrada se calcula como concentración de entrada por caudal de entrada.\",\n            \"latex\": r\"\\text{entrada}=r_ec_e\",\n        },\n        {\n            \"titulo\": \"Salida con volumen constante\",\n            \"descripcion\": \"Si el tanque está bien mezclado, la concentración interna es A/V y la salida de soluto es caudal por concentración interna.\",\n            \"latex\": r\"\\text{salida}=r_s\\frac{A}{V}\",\n        },\n        {\n            \"titulo\": \"Ecuación diferencial lineal\",\n            \"descripcion\": \"Cuando los caudales son iguales, el volumen permanece constante y aparece una EDO lineal.\",\n            \"latex\": r\"\\frac{dA}{dt}=r_ec_e-\\frac{r_s}{V}A\",\n        },\n        {\n            \"titulo\": \"Solución alrededor del equilibrio\",\n            \"descripcion\": \"Si re=rs=r, el equilibrio es A∞=Vc_e y la solución decae hacia ese valor.\",\n            \"latex\": r\"A(t)=Vc_e+(A_0-Vc_e)e^{-(r/V)t}\",\n        },\n    ],\n    (\"mezclas\", \"volumen_variable\"): [\n        {\n            \"titulo\": \"Volumen variable del tanque\",\n            \"descripcion\": \"Cuando entran y salen caudales distintos, el volumen cambia linealmente con el tiempo.\",\n            \"latex\": r\"V(t)=V_0+(r_e-r_s)t\",\n        },\n        {\n            \"titulo\": \"Balance de soluto\",\n            \"descripcion\": \"La entrada de soluto es constante si la concentración de entrada y el caudal de entrada son constantes; la salida depende de A/V(t).\",\n            \"latex\": r\"\\frac{dA}{dt}=r_ec_e-r_s\\frac{A}{V(t)}\",\n        },\n        {\n            \"titulo\": \"Ecuación lineal con coeficiente variable\",\n            \"descripcion\": \"La ecuación se escribe en forma estándar para resolverla con factor integrante.\",\n            \"latex\": r\"\\frac{dA}{dt}+\\frac{r_s}{V_0+(r_e-r_s)t}A=r_ec_e\",\n        },\n        {\n            \"titulo\": \"Estructura de solución usada\",\n            \"descripcion\": \"El sistema conserva una expresión simbólica dependiente de V(t), que SymPy puede evaluar cuando el tiempo objetivo existe.\",\n            \"latex\": r\"A(t)=c_eV(t)+(A_0-c_eV_0)\\left(\\frac{V_0}{V(t)}\\right)^{\\frac{r_s}{r_e-r_s}}\",\n        },\n    ],\n}\n\n\n_ALIASES: dict[tuple[str, str], tuple[str, str]] = {\n    (\"decaimiento\", \"default\"): (\"decaimiento\", \"decaimiento_radiactivo\"),\n}\n\n\ndef obtener_pasos_derivacion(modulo: str, variante: str) -> list[Paso]:\n    \"\"\"Obtiene una copia de los pasos teóricos para no mutar la plantilla global.\"\"\"\n    clave = (modulo, variante)\n    if clave not in DERIVACIONES and clave in _ALIASES:\n        clave = _ALIASES[clave]\n    return deepcopy(DERIVACIONES.get(clave, []))"
};
