function ayudaVariante({ titulo, contexto, formulaGeneral, pasosLatex, comprobacion, comprobacionLatex, ejemplo, codigo }) {
    return { titulo, contexto, formulaGeneral, pasosLatex, comprobacion, comprobacionLatex, ejemplo, codigo };
}

function ayudaDecaimientoBase({ titulo, variable, contexto, ejemplo, codigo }) {
    return ayudaVariante({
        titulo,
        contexto,
        formulaGeneral: `${variable}(t)=${variable}_0e^{-kt}`,
        pasosLatex: [
            `\\frac{d${variable}}{dt}=-k${variable}`,
            `\\frac{1}{${variable}}d${variable}=-kdt`,
            `\\ln|${variable}|=-kt+C`,
            `${variable}(t)=Ce^{-kt}`,
            `${variable}(0)=${variable}_0\\Rightarrow C=${variable}_0`,
            `${variable}(t)=${variable}_0e^{-kt}`,
            `k=\\frac{1}{t_1}\\ln\\left(\\frac{${variable}_0}{${variable}_1}\\right)`,
            `t=\\frac{1}{k}\\ln\\left(\\frac{${variable}_0}{${variable}_f}\\right)`
        ],
        comprobacion: `Al derivar ${variable}0e^{-kt}, aparece -k multiplicando la misma función, por eso cumple el modelo de decaimiento.`,
        comprobacionLatex: `${variable}'(t)=-k${variable}_0e^{-kt}=-k${variable}(t)`,
        ejemplo,
        codigo
    });
}

function ayudaNewton({ titulo, contexto, ejemplo, codigo }) {
    return ayudaVariante({
        titulo,
        contexto,
        formulaGeneral: "T(t)=T_a+(T_0-T_a)e^{-kt}",
        pasosLatex: [
            "\\frac{dT}{dt}=-k(T-T_a)",
            "u=T-T_a",
            "\\frac{du}{dt}=-ku",
            "\\frac{1}{u}du=-kdt",
            "u(t)=Ce^{-kt}",
            "T(t)-T_a=Ce^{-kt}",
            "T(0)=T_0\\Rightarrow C=T_0-T_a",
            "T(t)=T_a+(T_0-T_a)e^{-kt}",
            "k=-\\frac{1}{t_1}\\ln\\left(\\frac{T_1-T_a}{T_0-T_a}\\right)"
        ],
        comprobacion: "Al derivar la temperatura, la parte constante Ta desaparece y queda -k multiplicando la diferencia térmica T-Ta.",
        comprobacionLatex: "T'(t)=-(k)(T_0-T_a)e^{-kt}=-k(T(t)-T_a)",
        ejemplo,
        codigo
    });
}

function escaparPlantilla(valor) {
    return String(valor ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;");
}

